    fn get_random_empty_point(
        width: u16,
        height: u16,
        snake: &Snake,
        avoid: impl Fn(&Point) -> bool,
        rng: &mut rand::rngs::StdRng,
        margin: u16,
    ) -> Option<Point> {
        let mut i = 0;
        loop {
            let min_x = 1 + margin;
            let max_x = (width - 1).saturating_sub(margin).max(min_x + 1);
            let min_y = 1 + margin;
            let max_y = (height - 1).saturating_sub(margin).max(min_y + 1);
            if min_x >= max_x || min_y >= max_y {
                return None;
            }
            let x = rng.gen_range(min_x..max_x);
            let y = rng.gen_range(min_y..max_y);
            let p = Point {
                x,
                y,
            };
            if !snake.body_map.contains_key(&p) && !avoid(&p) {
                return Some(p);
            }
            i += 1;
            if i >= 100 {
                let mut empty = Vec::new();
                for y_ in min_y..max_y {
                    for x_ in min_x..max_x {
                        let p_ = Point {
                            x: x_,
                            y: y_,
                        };
                        if !snake.body_map.contains_key(&p_) && !avoid(&p_) {
                            empty.push(p_);
                        }
                    }
                }
                if !empty.is_empty() {
                    let idx = rng.gen_range(0..empty.len());
                    return Some(empty[idx]);
                }
                return None;
            }
        }
    }
    fn manage_turrets(&mut self) {
        let mut new_lasers = Vec::new();
        for turret in &mut self.turrets {
            turret.shoot_timer += 1;
            if turret.shoot_timer >= 10 {
                let mut target_dir = None;
                let mut min_dist = u32::MAX;

                let mut possible_targets = Vec::new();
                for boss in &self.bosses {
                    possible_targets.push(boss.position);
                }
                if let Some(goblin) = &self.goblin {
                    possible_targets.push(goblin.position);
                }
                for meteor in &self.meteors {
                    possible_targets.push(meteor.position);
                }

                if turret.is_enemy {
                    possible_targets.clear();
                    for body_part in &self.snake.body {
                        possible_targets.push(*body_part);
                    }
                    if let Some(p2) = &self.player2 {
                        for body_part in &p2.body {
                            possible_targets.push(*body_part);
                        }
                    }
                    if let Some((decoy_pos, _)) = self.decoy {
                        possible_targets.push(decoy_pos);
                    }
                }

                for target in possible_targets {
                    if target.x == turret.position.x || target.y == turret.position.y {
                        let dist = u32::from(turret.position.x.abs_diff(target.x))
                            + u32::from(turret.position.y.abs_diff(target.y));
                        if dist < min_dist {
                            min_dist = dist;
                            if target.x == turret.position.x && target.y < turret.position.y {
                                target_dir = Some(Direction::Up);
                            } else if target.x == turret.position.x && target.y > turret.position.y
                            {
                                target_dir = Some(Direction::Down);
                            } else if target.y == turret.position.y && target.x < turret.position.x
                            {
                                target_dir = Some(Direction::Left);
                            } else if target.y == turret.position.y && target.x > turret.position.x
                            {
                                target_dir = Some(Direction::Right);
                            }
                        }
                    }
                }

                if let Some(dir) = target_dir {
                    turret.shoot_timer = 0;
                    new_lasers.push(Laser {
                        position: turret.position,
                        direction: dir,
                        player: if turret.is_enemy {
                            3
                        } else {
                            1
                        },
                    });
                }
            }
        }
        self.lasers.extend(new_lasers);
    }

    fn manage_turret_battery(&mut self) {
        if self.mode != GameMode::TurretBattery {
            return;
        }
        // The skies stay clear so every turret and beam is always visible
        self.weather = Weather::Clear;
        // Keep the battery fully armed: re-seed missing enemy turrets on fair cells
        let enemy_count = self.turrets.iter().filter(|t| t.is_enemy).count();
        if enemy_count < Self::TURRET_BATTERY_COUNT {
            let spawn_x = self.width / 2;
            let spawn_y = self.height / 2;
            let next_heads = self.singularity_next_heads();
            for _ in enemy_count..Self::TURRET_BATTERY_COUNT {
                let avoid_turret = |p: &Point| {
                    self.obstacles.contains(p)
                        || self.mines.contains(p)
                        || *p == self.food
                        || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                        || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                        || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                        || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                        || self.black_hole == Some(*p)
                        || self.tornado == Some(*p)
                        || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                        || self.bosses.iter().any(|b| b.position == *p)
                        || self.turrets.iter().any(|t| t.position == *p)
                        || self.lasers.iter().any(|l| l.position == *p)
                        || self.snake.body_map.contains_key(p)
                        || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                        || self.bots.iter().any(|b| b.body_map.contains_key(p))
                        || next_heads.contains(p)
                        || p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) < 5
                };
                match Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_turret,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    Some(pos) => {
                        self.turrets.push(Turret {
                            position: pos,
                            shoot_timer: 0,
                            is_enemy: true,
                        });
                        self.spawn_particles(
                            f32::from(pos.x),
                            f32::from(pos.y),
                            10,
                            crate::color::Color::DarkRed,
                            'T',
                        );
                    },
                    None => break,
                }
            }
        }
        // While jammed (right after eating food) the battery holds its fire
        if self.turret_jammed > 0 {
            self.turret_jammed = self.turret_jammed.saturating_sub(1);
            return;
        }
        // Scheduled volley: every 6th tick every enemy turret fires one laser in
        // a shuffled random direction. Fairness: a beam fizzles when its first
        // cell is out of bounds or unsafe (never onto a snake, an entity, or the
        // cell any snake is about to enter), so a volley is dangerous but never cheap
        if self.tick_counter.is_multiple_of(6) {
            self.turret_volleys += 1;
            let battery: Vec<Point> = self
                .turrets
                .iter()
                .filter(|t| t.is_enemy)
                .map(|t| t.position)
                .collect();
            let mut fired = 0u32;
            for tp in &battery {
                let tp = *tp;
                let mut dirs = [
                    Direction::Up,
                    Direction::Down,
                    Direction::Left,
                    Direction::Right,
                ];
                for i in (1..dirs.len()).rev() {
                    let j = self.rng.gen_range(0..=i);
                    dirs.swap(i, j);
                }
                for dir in dirs {
                    let first = Self::calculate_next_head_dir(tp, dir);
                    if first.x == 0
                        || first.x >= self.width - 1
                        || first.y == 0
                        || first.y >= self.height - 1
                        || !self.singularity_cell_free(first)
                    {
                        continue;
                    }
                    self.lasers.push(Laser {
                        position: tp,
                        direction: dir,
                        player: 3,
                    });
                    fired += 1;
                    self.spawn_particles(
                        f32::from(tp.x),
                        f32::from(tp.y),
                        6,
                        crate::color::Color::Red,
                        '!',
                    );
                    break;
                }
            }
            if fired > 0
                && let Some(tp) = battery.first()
            {
                self.spawn_floating_text(
                    f32::from(tp.x),
                    f32::from(tp.y),
                    format!("Volley! ({fired} beams)"),
                    crate::color::Color::Red,
                );
            }
        }
    }

    #[expect(
        clippy::too_many_lines,
        reason = "Game loop inherently requires handling multiple states and events"
    )]
    fn manage_goblin(&mut self) {
        let spawn_chance = if self.mode == GameMode::SnakeSurvivor {
            0.05 // Spawns frequently in Survivor
        } else if self.time_of_day == crate::game::TimeOfDay::Night {
            0.02
        } else {
            0.005
        };
        let can_spawn = if self.mode == GameMode::SnakeSurvivor {
            self.goblin.is_none() && self.rng.gen_bool(spawn_chance) // Ignore bosses being empty in survivor
        } else {
            self.goblin.is_none() && self.rng.gen_bool(spawn_chance) && self.bosses.is_empty()
        };

        if can_spawn {
            let margin = if self.mode == GameMode::BattleRoyale {
                self.safe_zone_margin
            } else {
                0
            };
            let avoid = |p: &Point| {
                self.obstacles.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.mines.contains(p)
                    || (self.portals.is_some()
                        && (p == &self.portals.unwrap().0 || p == &self.portals.unwrap().1))
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
            };
            if let Some(spawn_pos) = Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid,
                &mut self.rng,
                margin,
            ) {
                self.goblin = Some(Goblin {
                    position: spawn_pos,
                    move_timer: 0,
                    food_eaten: 0,
                });
                self.spawn_particles(
                    f32::from(spawn_pos.x),
                    f32::from(spawn_pos.y),
                    20,
                    crate::color::Color::Yellow,
                    'G',
                );
            }
        }
        let mut despawn = false;
        let mut new_food_needed = false;
        let mut particle_spawns = Vec::new();
        if let Some(mut goblin) = self.goblin {
            goblin.move_timer += 1;
            if goblin.move_timer >= 2 {
                goblin.move_timer = 0;
                let target = self.food;
                if let Some(dir) = self.bot_smart_pathfind(goblin.position, target, 3) {
                    let next_pos = Self::calculate_next_head_dir(goblin.position, dir);
                    let margin = if self.mode == GameMode::BattleRoyale {
                        self.safe_zone_margin
                    } else {
                        0
                    };
                    if next_pos.x > margin
                        && next_pos.x < self.width - 1 - margin
                        && next_pos.y > margin
                        && next_pos.y < self.height - 1 - margin
                        && !self.obstacles.contains(&next_pos)
                    {
                        goblin.position = next_pos;
                        if goblin.position == self.food {
                            goblin.food_eaten += 1;
                            new_food_needed = true;
                            particle_spawns.push((
                                f32::from(goblin.position.x),
                                f32::from(goblin.position.y),
                                15,
                                crate::color::Color::Green,
                                '-',
                            ));
                            if goblin.food_eaten >= 3 {
                                despawn = true;
                                particle_spawns.push((
                                    f32::from(goblin.position.x),
                                    f32::from(goblin.position.y),
                                    30,
                                    crate::color::Color::White,
                                    '\\',
                                ));
                            }
                        }
                    }
                }
            }
            self.goblin = Some(goblin);
        }
        for (x, y, count, color, char) in particle_spawns {
            self.spawn_particles(x, y, count, color, char);
        }
        if new_food_needed {
            let margin = if self.mode == GameMode::BattleRoyale {
                self.safe_zone_margin
            } else {
                0
            };
            let avoid_food = |p: &Point| {
                self.obstacles.contains(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
            };
            if let Some(new_food) = Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid_food,
                &mut self.rng,
                margin,
            ) {
                self.food = new_food;
            }
        }
        if despawn {
            self.goblin = None;
        }
    }
    fn meteor_safe_spawn_columns(&self, min_x: u16, max_x: u16, drift: bool) -> Vec<u16> {
        // Fairness: never spawn a meteor in the column a snake currently
        // occupies or is about to enter, and never in a column that already
        // has a meteor in flight
        let mut forbidden: Vec<u16> = Vec::new();
        let mut snakes: Vec<&Snake> = vec![&self.snake];
        if let Some(p2) = &self.player2 {
            snakes.push(p2);
        }
        snakes.extend(self.bots.iter());
        for s in &snakes {
            for seg in &s.body {
                forbidden.push(seg.x);
            }
            let head = s.head();
            forbidden.push(Self::calculate_next_head_dir(head, s.direction).x);
        }
        for m in &self.meteors {
            forbidden.push(m.position.x);
        }
        let mut pool: Vec<u16> = (min_x..max_x).filter(|x| !forbidden.contains(x)).collect();
        if drift {
            // Drift fairness: a drifting meteor sweeps sideways while it falls, so also
            // skip columns from which a meteor with vx = ±1 would hit a snake cell.
            let margin = if self.mode == GameMode::BattleRoyale {
                self.safe_zone_margin
            } else {
                0
            };
            let y0 = margin + 1; // spawn row
            let mut snake_cells: Vec<Point> = Vec::new();
            for s in &snakes {
                snake_cells.extend(s.body.iter().copied());
                snake_cells.push(Self::calculate_next_head_dir(s.head(), s.direction));
            }
            let max_steps = self.height.saturating_mul(2);
            pool.retain(|&x| {
                [1, -1].iter().all(|&vx| {
                    let m = Meteor {
                        position: Point { x, y: y0 },
                        timer: 0,
                        vx,
                    };
                    !(1..=max_steps).any(|s| {
                        self.meteor_position_after(m, s)
                            .is_some_and(|p| snake_cells.contains(&p))
                    })
                })
            });
        }
        pool
    }
    fn register_meteor_impact(&mut self, impact: Point) {
        if self.mode != GameMode::Asteroids {
            return;
        }
        self.asteroid_impacts += 1;
        crate::game::beep();
        // The blast carves a small crater: obstacles adjacent to the impact cell are destroyed
        let mut crater = Vec::with_capacity(4);
        if impact.x > 0 {
            crater.push(Point {
                x: impact.x - 1,
                y: impact.y,
            });
        }
        if impact.x + 1 < self.width {
            crater.push(Point {
                x: impact.x + 1,
                y: impact.y,
            });
        }
        if impact.y > 0 {
            crater.push(Point {
                x: impact.x,
                y: impact.y - 1,
            });
        }
        if impact.y + 1 < self.height {
            crater.push(Point {
                x: impact.x,
                y: impact.y + 1,
            });
        }
        for p in crater {
            if self.obstacles.contains(&p) {
                self.remove_obstacle_and_hazards(p);
                self.spawn_particles(
                    f32::from(p.x),
                    f32::from(p.y),
                    5,
                    crate::color::Color::DarkYellow,
                    'x',
                );
            }
        }
    }
    #[must_use]
    pub fn meteor_impact_cells(&self) -> Vec<Point> {
        // Telegraph where each falling meteor will crash: the first blocked cell
        // (obstacle or mine) along its predicted trajectory, or the bottom row
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let ground = self.height.saturating_sub(1).saturating_sub(margin);
        let max_steps = self.height.saturating_mul(2);
        let (lo, hi) = self.meteor_drift_bounds();
        let mut cells = Vec::with_capacity(self.meteors.len());
        for meteor in &self.meteors {
            let mut impact = Point {
                x: meteor.position.x,
                y: ground,
            };
            for s in 1..=max_steps {
                if let Some(p) = self.meteor_position_after(*meteor, s) {
                    if self.obstacles.contains(&p) || self.mines.contains(&p) {
                        impact = p;
                        break;
                    }
                } else {
                    // The meteor reaches the ground at this step; its final
                    // column follows the (possibly bounced) drift trajectory
                    let drift = (ground / 2).saturating_sub(meteor.position.y / 2);
                    impact = Point {
                        x: Self::bounced_x(meteor.position.x, meteor.vx, drift, lo, hi),
                        y: ground,
                    };
                    break;
                }
            }
            cells.push(impact);
        }
        cells
    }
    fn remove_obstacle_and_hazards(&mut self, p: Point) {
        self.obstacles.remove(&p);
        self.snow_tiles.remove(&p);
        self.sand_tiles.remove(&p);
        self.lava_tiles.remove(&p);
        self.fire_tiles.remove(&p);
        self.blaze_tiles.remove(&p);
        self.acid_puddles.remove(&p);
        self.rubble_tiles.remove(&p);
        self.seismic_rubble.remove(&p);
    }
    fn manage_meteors(&mut self) {
        let asteroids = self.mode == GameMode::Asteroids;
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let min_x = margin + 1;
        let max_x = (self.width - 1).saturating_sub(margin).max(min_x);
        if self.rng.gen_bool(if asteroids || self.mode == GameMode::MeteorShower {
            0.15
        } else {
            0.01
        }) && max_x > min_x {
            let spawn_x = if asteroids {
                let allowed = self.meteor_safe_spawn_columns(min_x, max_x, false);
                if allowed.is_empty() {
                    None
                } else {
                    Some(allowed[self.rng.gen_range(0..allowed.len())])
                }
            } else {
                Some(self.rng.gen_range(min_x..max_x))
            };
            if let Some(spawn_x) = spawn_x {
                self.meteors.push(Meteor {
                    position: Point {
                        x: spawn_x,
                        y: margin + 1,
                    },
                    timer: 0,
                    vx: 0,
                });
            }
        }
        // Scheduled meteor showers in Asteroids mode: every 12th tick a burst of
        // up to 3 meteors falls in distinct fairness-checked columns; the first
        // meteor of the burst sweeps sideways (vx = ±1)
        if asteroids && self.tick_counter.is_multiple_of(12) && max_x > min_x {
            self.meteor_showers += 1;
            let mut allowed = self.meteor_safe_spawn_columns(min_x, max_x, true);
            for i in 0..3 {
                if allowed.is_empty() {
                    break;
                }
                let idx = self.rng.gen_range(0..allowed.len());
                let spawn_x = allowed.swap_remove(idx);
                let vx = if i == 0 {
                    if self.rng.gen_bool(0.5) { 1 } else { -1 }
                } else {
                    0
                };
                self.meteors.push(Meteor {
                    position: Point {
                        x: spawn_x,
                        y: margin + 1,
                    },
                    timer: 0,
                    vx,
                });
            }
        }
        // Meteor Shower mode: a strike is guaranteed on every 6th tick
        if self.mode == GameMode::MeteorShower
            && self.tick_counter.is_multiple_of(6)
            && max_x > min_x
            && let Some(strike_x) = self.pick_safe_strike_column(min_x, max_x)
        {
            self.meteor_strikes += 1;
            self.meteor_strike_column = Some(strike_x);
            self.meteors.push(Meteor {
                position: Point {
                    x: strike_x,
                    y: margin + 1,
                },
                timer: 0,
                vx: 0,
            });
        }
        let mut meteors_to_keep = Vec::new();
        for mut meteor in std::mem::take(&mut self.meteors) {
            meteor.timer += 1;
            if meteor.timer >= 2 {
                meteor.timer = 0;
                meteor.position.y += 1;
                // Drift one column per two fallen rows (on even rows), bouncing at the walls.
                if meteor.vx != 0 && meteor.position.y % 2 == 0 {
                    let (lo, hi) = self.meteor_drift_bounds();
                    let next_x = i32::from(meteor.position.x) + i32::from(meteor.vx);
                    if next_x < i32::from(lo) || next_x > i32::from(hi) {
                        meteor.vx = -meteor.vx;
                        meteor.position.x = u16::try_from(
                            (i32::from(meteor.position.x) + i32::from(meteor.vx))
                                .clamp(i32::from(lo), i32::from(hi)),
                        )
                        .unwrap_or(lo);
                    } else {
                        meteor.position.x = u16::try_from(next_x).unwrap_or(lo);
                    }
                }
            }
            if meteor.position.y >= self.height - 1 - margin {
                self.spawn_particles(
                    f32::from(meteor.position.x),
                    f32::from(meteor.position.y),
                    10,
                    crate::color::Color::Red,
                    '*',
                );
                self.register_meteor_impact(meteor.position);
                continue;
            }
            if self.obstacles.contains(&meteor.position) {
                self.remove_obstacle_and_hazards(meteor.position);
                self.spawn_particles(
                    f32::from(meteor.position.x),
                    f32::from(meteor.position.y),
                    20,
                    crate::color::Color::Red,
                    'X',
                );
                crate::game::beep();
                self.register_meteor_impact(meteor.position);
                continue;
            }
            if self.obstacles.contains(&meteor.position) {
                self.remove_obstacle_and_hazards(meteor.position);
                self.spawn_particles(
                    f32::from(meteor.position.x),
                    f32::from(meteor.position.y),
                    40,
                    crate::color::Color::Red,
                    'X',
                );
                crate::game::beep();
                self.register_meteor_impact(meteor.position);
                continue;
            }
            if self.mines.contains(&meteor.position) {
                self.mines.remove(&meteor.position);
                self.spawn_particles(
                    f32::from(meteor.position.x),
                    f32::from(meteor.position.y),
                    40,
                    crate::color::Color::Red,
                    'X',
                );
                beep();
                self.register_meteor_impact(meteor.position);
                continue;
            }
            meteors_to_keep.push(meteor);
        }
        self.meteors = meteors_to_keep;
    }
    fn meteor_drift_bounds(&self) -> (u16, u16) {
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let lo = margin + 1;
        let hi = self.width.saturating_sub(2).saturating_sub(margin).max(lo);
        (lo, hi)
    }
    fn bounced_x(start: u16, vx: i8, steps: u16, lo: u16, hi: u16) -> u16 {
        if vx == 0 || hi <= lo {
            return start.clamp(lo, hi);
        }
        let span = i32::from(hi - lo);
        let raw = (i32::from(start) - i32::from(lo) + i32::from(vx) * i32::from(steps))
            .rem_euclid(2 * span);
        let t = if raw > span { 2 * span - raw } else { raw };
        u16::try_from(i32::from(lo) + t).unwrap_or(lo)
    }
    #[must_use]
    pub fn meteor_position_after(&self, m: Meteor, steps: u16) -> Option<Point> {
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let ground = self.height.saturating_sub(1).saturating_sub(margin);
        let t0 = u16::from(m.timer.min(1));
        let fall = u16::midpoint(t0, steps);
        let y = m.position.y.saturating_add(fall);
        if y >= ground {
            return None;
        }
        let (lo, hi) = self.meteor_drift_bounds();
        // Drift one column per two fallen rows: count the even rows in (y, y + fall].
        let drift = (y / 2).saturating_sub(m.position.y / 2);
        Some(Point {
            x: Self::bounced_x(m.position.x, m.vx, drift, lo, hi),
            y,
        })
    }
    fn meteor_would_hit(&self, m: Meteor, p: Point, steps: u16) -> bool {
        if m.position == p {
            return true;
        }
        if p.y < m.position.y {
            return false;
        }
        let dy = u32::from(p.y - m.position.y);
        let t0 = u32::from(m.timer.min(1));
        let (lo, hi) = self.meteor_drift_bounds();
        let steps = u32::from(steps);
        let base = (2 * dy).saturating_sub(t0);
        for s in [base, base + 1] {
            if s >= 1 && s <= steps {
                let fall = u32::midpoint(t0, s);
                let y = m
                    .position
                    .y
                    .saturating_add(u16::try_from(fall).unwrap_or(0));
                let drift = u32::from(y / 2).saturating_sub(u32::from(m.position.y / 2));
                if y == p.y
                    && Self::bounced_x(
                        m.position.x,
                        m.vx,
                        u16::try_from(drift).unwrap_or(u16::MAX),
                        lo,
                        hi,
                    ) == p.x
                {
                    return true;
                }
            }
        }
        false
    }
    fn meteor_lane_penalty(&self, p: Point) -> u32 {
        let mut penalty = 0u32;
        for m in &self.meteors {
            if m.vx == 0 {
                continue;
            }
            for step in 1..=10_u16 {
                if let Some(mp) = self.meteor_position_after(*m, step) {
                    if mp == p {
                        penalty = penalty.saturating_add(500_000);
                    } else {
                        let d = self.travel_dist(p, mp, false);
                        if d < 3 {
                            penalty =
                                penalty.saturating_add(u32::from(3 - d).saturating_mul(100_000));
                        }
                    }
                }
            }
        }
        penalty
    }
    fn meteor_edge_cost(&self, p: Point) -> u16 {
        let mut cost = 0u16;
        for m in &self.meteors {
            if m.vx == 0 {
                continue;
            }
            for step in 1..=10_u16 {
                if let Some(mp) = self.meteor_position_after(*m, step) {
                    let dx = p.x.abs_diff(mp.x);
                    if dx < 2 && p.y >= mp.y {
                        let dy = p.y.abs_diff(mp.y);
                        if dy < 10 {
                            cost = cost.saturating_add((10 - dy).saturating_mul(10_000));
                        }
                    }
                }
            }
        }
        cost
    }
    fn rock_safe_rows(&self, min_y: u16, max_y: u16) -> Vec<u16> {
        // Fairness: never roll a rock down a row any snake currently
        // occupies or is about to enter, and never down a row that already
        // has a rock rolling through it
        let mut forbidden: Vec<u16> = Vec::new();
        let mut snakes: Vec<&Snake> = vec![&self.snake];
        if let Some(p2) = &self.player2 {
            snakes.push(p2);
        }
        snakes.extend(self.bots.iter());
        for s in &snakes {
            for seg in &s.body {
                forbidden.push(seg.y);
            }
        }
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let mut next_cells = vec![p1_next];
        if let Some(p2) = &self.player2 {
            next_cells.push(Self::calculate_next_head_dir(p2.head(), p2.direction));
        }
        for b in &self.bots {
            let d = b.direction_queue.front().copied().unwrap_or(b.direction);
            next_cells.push(Self::calculate_next_head_dir(b.head(), d));
        }
        for p in &next_cells {
            forbidden.push(p.y);
        }
        for b in &self.rocks {
            forbidden.push(b.position.y);
        }
        (min_y..max_y).filter(|y| !forbidden.contains(y)).collect()
    }
    fn spawn_rock(&mut self, y: u16) {
        let direction = if self.rng.gen_bool(0.5) {
            Direction::Right
        } else {
            Direction::Left
        };
        let x = if direction == Direction::Right {
            0
        } else {
            self.width.saturating_sub(1)
        };
        self.rocks.push(LandslideRock {
            position: Point { x, y },
            direction,
        });
        self.landslide_rolls += 1;
        let head = self.snake.head();
        self.spawn_floating_text(
            f32::from(head.x),
            f32::from(head.y),
            "Landslide!".to_string(),
            crate::color::Color::White,
        );
    }
    #[must_use]
    pub fn rock_position_after(&self, b: LandslideRock, steps: u16) -> Option<Point> {
        // A rock rolls one cell per tick in its direction until it leaves the board
        let x = match b.direction {
            Direction::Right => i32::from(b.position.x) + i32::from(steps),
            Direction::Left => i32::from(b.position.x) - i32::from(steps),
            Direction::Up | Direction::Down => i32::from(b.position.x),
        };
        if x < 0 || x >= i32::from(self.width) {
            return None;
        }
        Some(Point {
            x: u16::try_from(x).unwrap_or(0),
            y: b.position.y,
        })
    }
    fn rock_would_hit(b: LandslideRock, p: Point, steps: u16) -> bool {
        if b.position == p {
            return true;
        }
        if p.y != b.position.y {
            return false;
        }
        let dx = u32::from(p.x.abs_diff(b.position.x));
        let steps = u32::from(steps);
        match b.direction {
            Direction::Right => p.x >= b.position.x && dx <= steps,
            Direction::Left => p.x <= b.position.x && dx <= steps,
            Direction::Up | Direction::Down => false,
        }
    }
    fn rock_lane_penalty(&self, p: Point) -> u32 {
        let mut penalty = 0u32;
        for b in &self.rocks {
            for step in 1..=10_u16 {
                if let Some(bp) = self.rock_position_after(*b, step) {
                    if bp == p {
                        penalty = penalty.saturating_add(500_000);
                    } else {
                        let d = self.travel_dist(p, bp, false);
                        if d < 3 {
                            penalty = penalty.saturating_add(u32::from(3 - d).saturating_mul(100_000));
                        }
                    }
                }
            }
        }
        penalty
    }
    fn rock_edge_cost(&self, p: Point) -> u16 {
        let mut cost = 0u16;
        for b in &self.rocks {
            for step in 1..=10_u16 {
                if let Some(bp) = self.rock_position_after(*b, step)
                    && bp.y == p.y
                {
                    let dx = p.x.abs_diff(bp.x);
                    if dx < 10 {
                        cost = cost.saturating_add((10 - dx).saturating_mul(1_000));
                    }
                }
            }
        }
        cost
    }
    fn manage_landslide(&mut self) {
        if self.mode != GameMode::Landslide {
            return;
        }
        // The snowstorm never breaks in Landslide mode
        self.weather = Weather::Snow;
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let min_y = margin + 1;
        let max_y = (self.height - 1).saturating_sub(margin).max(min_y);
        // Ambient rumble: a rock occasionally rolls in on top of the schedule
        if self.rocks.len() < Self::MAX_ROCKS && self.rng.gen_bool(0.05) && max_y > min_y {
            let allowed = self.rock_safe_rows(min_y, max_y);
            if !allowed.is_empty() {
                let y = allowed[self.rng.gen_range(0..allowed.len())];
                self.spawn_rock(y);
            }
        }
        // Scheduled landslide: every 6th tick a rock is guaranteed to roll in
        // (the rock cap only limits the ambient rumble, never the schedule)
        if self.tick_counter.is_multiple_of(6) && max_y > min_y {
            let allowed = self.rock_safe_rows(min_y, max_y);
            if !allowed.is_empty() {
                let y = allowed[self.rng.gen_range(0..allowed.len())];
                self.spawn_rock(y);
            }
        }
        // Roll every rock one cell; it smashes through obstacles and mines
        let mut kept = Vec::new();
        for mut rock in std::mem::take(&mut self.rocks) {
            let next = Self::calculate_next_head_dir(rock.position, rock.direction);
            if next.x >= self.width || next.y >= self.height {
                continue; // rolled off the board
            }
            rock.position = next;
            if self.obstacles.contains(&rock.position) {
                self.remove_obstacle_and_hazards(rock.position);
                self.spawn_particles(
                    f32::from(rock.position.x),
                    f32::from(rock.position.y),
                    20,
                    crate::color::Color::White,
                    'O',
                );
                crate::game::beep();
            }
            if self.mines.contains(&rock.position) {
                self.mines.remove(&rock.position);
                self.spawn_particles(
                    f32::from(rock.position.x),
                    f32::from(rock.position.y),
                    20,
                    crate::color::Color::White,
                    'O',
                );
                crate::game::beep();
            }
            kept.push(rock);
        }
        self.rocks = kept;
    }
    fn comet_ignite(&mut self, p: Point) {
        self.fire_tiles.insert(p);
        self.fire_ttl.insert(p, Self::COMET_TAIL_TICKS);
        self.obstacles.insert(p);
        self.ash_tiles.remove(&p);
    }
    // A comet streaks one cell per tick along its diagonal (dx, dy) until it
    // leaves the board; returns None once the predicted cell is off the board
    #[must_use]
    pub fn comet_position_after(&self, c: Comet, steps: u16) -> Option<Point> {
        let x = i32::from(c.position.x) + i32::from(c.dx) * i32::from(steps);
        let y = i32::from(c.position.y) + i32::from(c.dy) * i32::from(steps);
        if x < 0 || y < 0 || x >= i32::from(self.width) || y >= i32::from(self.height) {
            return None;
        }
        Some(Point {
            x: u16::try_from(x).unwrap_or(0),
            y: u16::try_from(y).unwrap_or(0),
        })
    }
    fn comet_would_hit(c: Comet, p: Point, steps: u16) -> bool {
        let sx = i32::from(p.x) - i32::from(c.position.x);
        let sy = i32::from(p.y) - i32::from(c.position.y);
        let tx = sx * i32::from(c.dx);
        let ty = sy * i32::from(c.dy);
        tx == ty && tx >= 0 && u32::try_from(tx).unwrap_or(u32::MAX) <= u32::from(steps)
    }
    // Fairness: a comet may only launch if its whole diagonal path avoids every
    // snake body segment and the cell every snake is about to enter
    fn comet_path_fair(&self, start: Point, dx: i8, dy: i8) -> bool {
        let next_heads = self.singularity_next_heads();
        let mut p = start;
        loop {
            if self.snake.body_map.contains_key(&p)
                || self
                    .player2
                    .as_ref()
                    .is_some_and(|p2| p2.body_map.contains_key(&p))
                || self.bots.iter().any(|b| b.body_map.contains_key(&p))
                || next_heads.contains(&p)
            {
                return false;
            }
            let nx = i32::from(p.x) + i32::from(dx);
            let ny = i32::from(p.y) + i32::from(dy);
            if nx < 0 || ny < 0 || nx >= i32::from(self.width) || ny >= i32::from(self.height) {
                return true;
            }
            p = Point {
                x: u16::try_from(nx).unwrap_or(0),
                y: u16::try_from(ny).unwrap_or(0),
            };
        }
    }
    fn launch_comet(&mut self) {
        for _ in 0..8 {
            // Launch from a random edge cell, always streaking inward
            let (start, dx, dy) = match self.rng.gen_range(0..4_u8) {
                0 => (
                    Point {
                        x: 0,
                        y: self.rng.gen_range(0..self.height),
                    },
                    1,
                    if self.rng.gen_bool(0.5) { 1 } else { -1 },
                ),
                1 => (
                    Point {
                        x: self.width.saturating_sub(1),
                        y: self.rng.gen_range(0..self.height),
                    },
                    -1,
                    if self.rng.gen_bool(0.5) { 1 } else { -1 },
                ),
                2 => (
                    Point {
                        x: self.rng.gen_range(0..self.width),
                        y: 0,
                    },
                    if self.rng.gen_bool(0.5) { 1 } else { -1 },
                    1,
                ),
                _ => (
                    Point {
                        x: self.rng.gen_range(0..self.width),
                        y: self.height.saturating_sub(1),
                    },
                    if self.rng.gen_bool(0.5) { 1 } else { -1 },
                    -1,
                ),
            };
            if self.comet_path_fair(start, dx, dy) {
                self.comets.push(Comet {
                    position: start,
                    dx,
                    dy,
                });
                self.comet_launches += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "Comet!".to_string(),
                    crate::color::Color::Yellow,
                );
                crate::game::beep();
                return;
            }
        }
    }
    fn comet_lane_penalty(&self, p: Point) -> u32 {
        let mut penalty = 0u32;
        for c in &self.comets {
            for step in 1..=10_u16 {
                if let Some(cp) = self.comet_position_after(*c, step) {
                    if cp == p {
                        penalty = penalty.saturating_add(500_000);
                    } else {
                        let d = self.travel_dist(p, cp, false);
                        if d < 3 {
                            penalty = penalty.saturating_add(u32::from(3 - d).saturating_mul(100_000));
                        }
                    }
                }
            }
        }
        penalty
    }
    fn comet_edge_cost(&self, p: Point) -> u16 {
        let mut cost = 0u16;
        for c in &self.comets {
            for step in 1..=10_u16 {
                if let Some(cp) = self.comet_position_after(*c, step) {
                    let d = p.x.abs_diff(cp.x) + p.y.abs_diff(cp.y);
                    if d < 10 {
                        cost = cost.saturating_add((10 - d).saturating_mul(1_000));
                    }
                }
            }
        }
        cost
    }
    fn manage_comet(&mut self) {
        if self.mode != GameMode::Comet {
            return;
        }
        // The sky never clouds over in Comet mode so comets stay visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale fire records
        self.fire_tiles.retain(|p| self.obstacles.contains(p));
        self.fire_ttl.retain(|p, _| self.fire_tiles.contains(p));
        // Trail burn-down: every burning cell has a limited lifetime, then it cools off
        let mut burned_out: Vec<Point> = Vec::new();
        for (p, ttl) in &mut self.fire_ttl {
            if *ttl <= 1 {
                burned_out.push(*p);
            } else {
                *ttl -= 1;
            }
        }
        for p in burned_out {
            self.fire_tiles.remove(&p);
            self.fire_ttl.remove(&p);
            self.obstacles.remove(&p);
        }
        // At tick 200 of every 250-tick cycle the sky clears: all comets burn out
        if self.tick_counter == 200 {
            if !self.comets.is_empty() {
                self.comets.clear();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The sky clears!".to_string(),
                    crate::color::Color::Cyan,
                );
            }
            return;
        }
        // Ambient streak: a rare extra launch on top of the schedule
        if self.comets.len() < Self::MAX_COMETS && self.rng.gen_bool(0.02) {
            self.launch_comet();
        }
        // Scheduled launch: every COMET_PERIOD-th tick a comet is guaranteed to streak across
        if self.tick_counter.is_multiple_of(Self::COMET_PERIOD)
            && self.comets.len() < Self::MAX_COMETS
        {
            self.launch_comet();
        }
        // Move every comet one cell diagonally, leaving a burning trail behind
        let mut kept = Vec::new();
        for mut comet in std::mem::take(&mut self.comets) {
            // The head cell burns while the comet occupies it
            self.comet_ignite(comet.position);
            let nx = i32::from(comet.position.x) + i32::from(comet.dx);
            let ny = i32::from(comet.position.y) + i32::from(comet.dy);
            if nx < 0 || ny < 0 || nx >= i32::from(self.width) || ny >= i32::from(self.height) {
                continue; // streaked off the board
            }
            comet.position = Point {
                x: u16::try_from(nx).unwrap_or(0),
                y: u16::try_from(ny).unwrap_or(0),
            };
            // A comet smashes through obstacles and mines in its path
            if self.obstacles.contains(&comet.position) {
                self.remove_obstacle_and_hazards(comet.position);
                self.spawn_particles(
                    f32::from(comet.position.x),
                    f32::from(comet.position.y),
                    20,
                    crate::color::Color::DarkYellow,
                    '*',
                );
                crate::game::beep();
            }
            if self.mines.contains(&comet.position) {
                self.mines.remove(&comet.position);
                self.spawn_particles(
                    f32::from(comet.position.x),
                    f32::from(comet.position.y),
                    20,
                    crate::color::Color::DarkYellow,
                    '*',
                );
            }
            self.comet_ignite(comet.position);
            kept.push(comet);
        }
        self.comets = kept;
    }
    fn manage_blizzard(&mut self) {
        if self.mode != GameMode::Blizzard {
            return;
        }
        // The storm never breaks in Blizzard mode
        self.weather = Weather::Snow;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale snow records
        self.snow_tiles.retain(|p| self.obstacles.contains(p));
        // Periodic thaw: all accumulated snow melts away
        if self.tick_counter == 200 {
            if !self.snow_tiles.is_empty() {
                for p in self.snow_tiles.drain() {
                    self.obstacles.remove(&p);
                }
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "Thawing!".to_string(),
                    crate::color::Color::Cyan,
                );
            }
            return;
        }
        // Snowfall accumulates on random empty cells
        if self.tick_counter.is_multiple_of(6) {
            let cap = (u32::from(self.width) * u32::from(self.height)) / 10;
            if u32::try_from(self.snow_tiles.len()).unwrap_or(u32::MAX) < cap {
                let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
                let p2_next = self
                    .player2
                    .as_ref()
                    .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
                let bot_next: Vec<Point> = self
                    .bots
                    .iter()
                    .map(|b| Self::calculate_next_head_dir(b.head(), b.direction))
                    .collect();
                let avoid = |p: &Point| {
                    *p == p1_next
                        || p2_next == Some(*p)
                        || bot_next.contains(p)
                        || self.obstacles.contains(p)
                        || self.snake.body_map.contains_key(p)
                        || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                        || self.bots.iter().any(|b| b.body_map.contains_key(p))
                        || *p == self.food
                        || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                        || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                        || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                        || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                        || self.mines.contains(p)
                        || self.black_hole == Some(*p)
                        || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                        || self.bosses.iter().any(|b| b.position == *p)
                        || self.companion.as_ref().is_some_and(|c| c.position == *p)
                        || self.turrets.iter().any(|t| t.position == *p)
                        || self.xp_gems.contains(p)
                        || self.painted_tiles.contains_key(p)
                        || self.equipment_boxes.contains(p)
                        || self.crops.iter().any(|c| c.position == *p)
                        || self.eggs_on_board.contains_key(p)
                        || self.koth_zone == Some(*p)
                        || self.p1_flag == Some(*p)
                        || self.p2_flag == Some(*p)
                        || self.resources.contains_key(p)
                        || self.lasers.iter().any(|l| l.position == *p)
                        || self.meteors.iter().any(|m| m.position == *p)
                || self.rocks.iter().any(|b| b.position == *p)
                };
                if let Some(pos) = Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    self.snow_tiles.insert(pos);
                    self.obstacles.insert(pos);
                }
            }
        }
    }
    fn manage_fortress(&mut self) {
        if self.mode != GameMode::Fortress {
            return;
        }
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale wall records
        self.fortress_walls.retain(|p| self.obstacles.contains(p));
        // Periodic retraction: at tick 200 of every 250-tick cycle the walls pull back
        if self.tick_counter == 200 {
            if !self.fortress_walls.is_empty() {
                for p in self.fortress_walls.drain() {
                    self.obstacles.remove(&p);
                }
                self.fortress_depth = 0;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The walls retract!".to_string(),
                    crate::color::Color::DarkGrey,
                );
            }
            return;
        }
        // Every 6th tick the fortress closes in one ring deeper
        if !self.tick_counter.is_multiple_of(6) {
            return;
        }
        // Cap the depth at a quarter of the short side so the inner keep always
        // stays roomy enough to play in.
        let max_depth = u16::min(self.width, self.height) / 4;
        if self.fortress_depth >= max_depth {
            return;
        }
        let depth = self.fortress_depth + 1;
        // Never erect a ring while any snake is outside it (in the outer band),
        // so the closing walls can never seal a snake in.
        let ring_dist = |p: &Point| {
            u16::min(p.x, p.y)
                .min(self.width - 1 - p.x)
                .min(self.height - 1 - p.y)
        };
        let snake_outside = self.snake.body.iter().any(|p| ring_dist(p) < depth)
            || self
                .player2
                .as_ref()
                .is_some_and(|p2| p2.body.iter().any(|p| ring_dist(p) < depth))
            || self
                .bots
                .iter()
                .any(|b| b.body.iter().any(|p| ring_dist(p) < depth));
        if snake_outside {
            return;
        }
        self.fortress_depth += 1;
        self.fortress_rings += 1;
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        let avoid = |p: &Point| {
            *p == p1_next
                || p2_next == Some(*p)
                || bot_next.contains(p)
                || self.obstacles.contains(p)
                || self.snake.body_map.contains_key(p)
                || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                || self.bots.iter().any(|b| b.body_map.contains_key(p))
                || *p == self.food
                || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                || self.mines.contains(p)
                || self.black_hole == Some(*p)
                || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                || self.bosses.iter().any(|b| b.position == *p)
                || self.companion.as_ref().is_some_and(|c| c.position == *p)
                || self.turrets.iter().any(|t| t.position == *p)
                || self.xp_gems.contains(p)
                || self.painted_tiles.contains_key(p)
                || self.equipment_boxes.contains(p)
                || self.crops.iter().any(|c| c.position == *p)
                || self.eggs_on_board.contains_key(p)
                || self.koth_zone == Some(*p)
                || self.p1_flag == Some(*p)
                || self.p2_flag == Some(*p)
                || self.resources.contains_key(p)
                || self.lasers.iter().any(|l| l.position == *p)
                || self.meteors.iter().any(|m| m.position == *p)
                || self.rocks.iter().any(|b| b.position == *p)
                || self.snow_tiles.contains(p)
                || self.sand_tiles.contains(p)
                || self.lava_tiles.contains(p)
                || self.rubble_tiles.contains(p)
                || self.seismic_rubble.contains(p)
                || self.acid_puddles.contains(p)
                || self.puddle_tiles.contains(p)
                || self.fire_tiles.contains(p)
                || self.ash_tiles.contains(p)
                || self.inferno_tiles.contains(p)
                || self.belt_tiles.contains_key(p)
                || self.ice_tiles.contains(p)
                || self.blaze_tiles.contains_key(p)
                || self.fortress_walls.contains(p)
                || self.thorn_tiles.contains(p)
        };
        let mut ring_cells = Vec::new();
        for x in 0..self.width {
            for y in 0..self.height {
                let p = Point { x, y };
                if ring_dist(&p) == depth && !avoid(&p) {
                    ring_cells.push(p);
                }
            }
        }
        let mut erected = 0u32;
        for p in ring_cells {
            self.fortress_walls.insert(p);
            self.obstacles.insert(p);
            erected += 1;
        }
        if erected > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The walls close in! (+{erected})"),
                crate::color::Color::DarkGrey,
            );
        }
    }
    fn manage_geyser(&mut self) {
        if self.mode != GameMode::Geyser {
            return;
        }
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale jet records
        self.geyser_jets.retain(|p, _| self.obstacles.contains(p));
        // Geyser vents are permanent fixtures: keep them blocked
        for vent in self.geyser_vents.clone() {
            self.obstacles.insert(vent);
            self.geyser_jets.insert(vent, u32::MAX);
        }
        // Each jet dissipates one tick at a time and then leaves open ground
        let dissipated: Vec<Point> = self
            .geyser_jets
            .iter()
            .filter(|(p, ticks)| **ticks <= 1 && !self.geyser_vents.contains(p))
            .map(|(p, _)| *p)
            .collect();
        for p in dissipated {
            self.geyser_jets.remove(&p);
            self.obstacles.remove(&p);
        }
        for ticks in self.geyser_jets.values_mut() {
            *ticks = ticks.saturating_sub(1);
        }
        // Periodic rest: at tick 200 of every 250-tick cycle the geysers rest (vents remain)
        if self.tick_counter == 200 {
            let vents = self.geyser_vents.clone();
            let doomed: Vec<Point> = self
                .geyser_jets
                .keys()
                .filter(|p| !vents.contains(p))
                .copied()
                .collect();
            let n = doomed.len();
            for p in doomed {
                self.geyser_jets.remove(&p);
                self.obstacles.remove(&p);
            }
            if n > 0 {
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The geysers rest!".to_string(),
                    crate::color::Color::DarkCyan,
                );
            }
            return;
        }
        // Scheduled eruption every 6th tick
        if self.tick_counter.is_multiple_of(6) {
            self.geyser_eruptions += 1;
            self.erupt_geyser();
        }
    }
    fn erupt_geyser(&mut self) {
        if self.geyser_vents.is_empty() {
            return;
        }
        let cap = (u32::from(self.width) * u32::from(self.height)) * 15 / 100;
        if u32::try_from(self.geyser_jets.len()).unwrap_or(u32::MAX) >= cap {
            return;
        }
        // Erupt from the vents in round-robin order
        let idx = (self.geyser_eruptions as usize).saturating_sub(1) % self.geyser_vents.len();
        let vent = self.geyser_vents[idx];
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        let dirs = [
            Direction::Up,
            Direction::Down,
            Direction::Left,
            Direction::Right,
        ];
        let mut sprayed = 0u32;
        for dir in dirs {
            let mut cur = vent;
            for _ in 0..Self::GEYSER_JET_RANGE {
                if u32::try_from(self.geyser_jets.len()).unwrap_or(u32::MAX) >= cap {
                    break;
                }
                let np = Self::calculate_next_head_dir(cur, dir);
                if np.x >= self.width || np.y >= self.height {
                    break;
                }
                if self.is_geyser_jet_blocked(np, p1_next, p2_next, &bot_next) {
                    break;
                }
                cur = np;
                self.geyser_jets.insert(np, Self::GEYSER_JET_TICKS);
                self.obstacles.insert(np);
                sprayed += 1;
            }
        }
        if sprayed > 0 {
            self.spawn_floating_text(
                f32::from(vent.x),
                f32::from(vent.y),
                format!("Geyser erupts! (+{sprayed})"),
                crate::color::Color::Cyan,
            );
        }
    }
    fn is_geyser_jet_blocked(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.obstacles.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.geyser_vents.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.tornado == Some(p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
    }
    fn spawn_geyser_vents(&mut self) {
        for _ in 0..2 {
            let avoid = |p: &Point| {
                self.obstacles.contains(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.mines.contains(p)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.geyser_vents.contains(p)
            };
            if let Some(pos) = Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid,
                &mut self.rng,
                0,
            ) {
                self.geyser_vents.push(pos);
                self.geyser_jets.insert(pos, u32::MAX);
                self.obstacles.insert(pos);
            }
        }
    }

    #[must_use]
    pub fn thorn_lashes(&self, p: Point) -> bool {
        if self.thorn_tiles.is_empty() {
            return false;
        }
        if self.thorn_tiles.contains(&p) {
            return true;
        }
        [Direction::Up, Direction::Down, Direction::Left, Direction::Right]
            .iter()
            .any(|&d| self.thorn_tiles.contains(&Self::calculate_next_head_dir(p, d)))
    }
    fn is_thorn_spread_blocked(&self, p: Point, next_heads: &[Point]) -> bool {
        if p.x == 0
            || p.x >= self.width - 1
            || p.y == 0
            || p.y >= self.height - 1
            || self.obstacles.contains(&p)
            || self.thorn_tiles.contains(&p)
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
        {
            return true;
        }
        // A thorn lashes at every orthogonally adjacent cell, so its whole lash
        // zone (itself plus its 4 neighbors) must stay clear of snakes and of
        // the cells snakes are about to enter, or the bloom would be a cheap kill
        let lash_zone = [
            p,
            Self::calculate_next_head_dir(p, Direction::Up),
            Self::calculate_next_head_dir(p, Direction::Down),
            Self::calculate_next_head_dir(p, Direction::Left),
            Self::calculate_next_head_dir(p, Direction::Right),
        ];
        self.snake.body_map.iter().any(|(bp, _)| lash_zone.contains(bp))
            || self
                .player2
                .as_ref()
                .is_some_and(|p2| p2.body_map.iter().any(|(bp, _)| lash_zone.contains(bp)))
            || self
                .bots
                .iter()
                .any(|b| b.body_map.iter().any(|(bp, _)| lash_zone.contains(bp)))
            || lash_zone.iter().any(|c| next_heads.contains(c))
    }
    fn spawn_initial_thorns(&mut self) {
        let thorn_count = (u32::from(self.width) * u32::from(self.height) / 100).max(2);
        let mut placed = 0u32;
        for _ in 0..thorn_count * 20 {
            if placed >= thorn_count {
                break;
            }
            let next_heads = self.next_head_cells();
            let avoid_thorn = |p: &Point| {
                self.obstacles.contains(p)
                    || self.thorn_tiles.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.mines.contains(p)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || next_heads.contains(p)
            };
            if let Some(p) = Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid_thorn,
                &mut self.rng,
                0,
            ) {
                // Keep the initial thorns away from the spawn area lash zones too
                if !self.is_thorn_spread_blocked(p, &next_heads) {
                    self.thorn_tiles.insert(p);
                    self.obstacles.insert(p);
                    placed += 1;
                }
            }
        }
    }
    fn manage_thornfield(&mut self) {
        if self.mode != GameMode::Thornfield {
            return;
        }
        // The skies stay clear in Thornfield mode so the briars always stay visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale thorn records
        self.thorn_tiles.retain(|p| self.obstacles.contains(p));
        // Periodic wither: at tick 200 of every 250-tick cycle all thorns wither away
        if self.tick_counter == 200 {
            if !self.thorn_tiles.is_empty() {
                let thorns: Vec<Point> = self.thorn_tiles.drain().collect();
                for p in thorns {
                    self.obstacles.remove(&p);
                }
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The thorns wither!".to_string(),
                    crate::color::Color::Green,
                );
            }
            return;
        }
        // Every 6th tick a bloom spreads the briars from the frontier
        if !self.tick_counter.is_multiple_of(6) {
            return;
        }
        let cap = (u32::from(self.width) * u32::from(self.height)) / 12;
        if u32::try_from(self.thorn_tiles.len()).unwrap_or(u32::MAX) >= cap {
            return;
        }
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let mut next_heads = vec![p1_next];
        if let Some(p2n) = p2_next {
            next_heads.push(p2n);
        }
        for b in &self.bots {
            let d = b.direction_queue.front().copied().unwrap_or(b.direction);
            next_heads.push(Self::calculate_next_head_dir(b.head(), d));
        }
        self.thorn_blooms += 1;
        let frontier: Vec<Point> = self.thorn_tiles.iter().copied().collect();
        let dirs = [
            Direction::Up,
            Direction::Down,
            Direction::Left,
            Direction::Right,
        ];
        let mut spread = 0u32;
        for _ in 0..3 {
            if frontier.is_empty()
                || u32::try_from(self.thorn_tiles.len()).unwrap_or(u32::MAX) >= cap
            {
                break;
            }
            let from = frontier[self.rng.gen_range(0..frontier.len())];
            let d = dirs[self.rng.gen_range(0..dirs.len())];
            let np = Self::calculate_next_head_dir(from, d);
            if self.is_thorn_spread_blocked(np, &next_heads) {
                continue;
            }
            self.thorn_tiles.insert(np);
            self.obstacles.insert(np);
            spread += 1;
        }
        if spread > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The briars bloom! (+{spread})"),
                crate::color::Color::Green,
            );
        }
    }
    fn domino_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 80).clamp(4, 10)
    }
    fn domino_cap(&self) -> usize {
        usize::from(self.width) * usize::from(self.height) * 15 / 100
    }
    // A cell a domino may fall onto must be fair right now: inside the playable
    // border and free of snakes (bodies and the cells they are about to enter)
    // and of every entity or hazard, so a topple can never crush anyone.
    fn is_domino_landing_blocked(&self, p: Point, next_heads: &[Point]) -> bool {
        let margin = self.safe_zone_margin;
        if p.x <= margin
            || p.x >= self.width.saturating_sub(1).saturating_sub(margin)
            || p.y <= margin
            || p.y >= self.height.saturating_sub(1).saturating_sub(margin)
            || self.obstacles.contains(&p)
            || self.domino_tiles.contains(&p)
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| pu.location == p)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.rocks.iter().any(|b| b.position == p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.thorn_tiles.contains(&p)
            || self.spike_tiles.contains_key(&p)
            || self.press_cells.contains(&p)
            || self.pinball_bumpers.contains(&p)
            || self.tramp_pads.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.geyser_vents.contains(&p)
            || self.mirage_foods.contains_key(&p)
            || self.phase_gates.contains(&p)
        {
            return true;
        }
        self.snake.body_map.contains_key(&p)
            || self
                .player2
                .as_ref()
                .is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || next_heads.contains(&p)
    }
    // A fresh domino may stand up on any fair cell; the spawn seed keeps a
    // Manhattan distance from the spawn point so the opening is never boxed in.
    fn domino_spawn_avoid(&self, p: Point, next_heads: &[Point], min_spawn_dist: u16) -> bool {
        if self.is_domino_landing_blocked(p, next_heads) {
            return true;
        }
        let spawn = Point {
            x: self.width / 2,
            y: self.height / 2,
        };
        p.x.abs_diff(spawn.x).saturating_add(p.y.abs_diff(spawn.y)) < min_spawn_dist
    }
    fn random_interior_point(&mut self) -> Point {
        Point {
            x: self.rng.gen_range(1..self.width.saturating_sub(1).max(2)),
            y: self.rng.gen_range(1..self.height.saturating_sub(1).max(2)),
        }
    }
    fn drop_fresh_domino(&mut self, next_heads: &[Point]) -> bool {
        for _ in 0..100 {
            let p = self.random_interior_point();
            if !self.snake.body_map.contains_key(&p) && !self.domino_spawn_avoid(p, next_heads, 0) {
                self.domino_tiles.insert(p);
                self.obstacles.insert(p);
                self.domino_drops += 1;
                return true;
            }
        }
        false
    }
    fn spawn_initial_dominoes(&mut self) {
        let next_heads = self.next_head_cells();
        let count = self.domino_count();
        for _ in 0..count * 20 {
            if self.domino_tiles.len() >= count {
                break;
            }
            let p = self.random_interior_point();
            if !self.snake.body_map.contains_key(&p) && !self.domino_spawn_avoid(p, &next_heads, 4)
            {
                self.domino_tiles.insert(p);
                self.obstacles.insert(p);
            }
        }
    }
    fn manage_domino(&mut self) {
        if self.mode != GameMode::Domino {
            return;
        }
        // The skies stay clear in Domino mode so the dominoes always stay visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale domino records
        self.domino_tiles.retain(|p| self.obstacles.contains(p));
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let mut next_heads = vec![p1_next];
        if let Some(p2n) = p2_next {
            next_heads.push(p2n);
        }
        for b in &self.bots {
            let d = b.direction_queue.front().copied().unwrap_or(b.direction);
            next_heads.push(Self::calculate_next_head_dir(b.head(), d));
        }
        // Periodic stand-again: at tick 200 of every 250-tick cycle every domino is
        // gathered up and re-seeded on fresh fair cells, never on a snake, on the
        // cell any snake is about to enter, on any entity, or within 4 cells of a head
        if self.tick_counter == 200 {
            let old: Vec<Point> = self.domino_tiles.drain().collect();
            for p in old {
                self.obstacles.remove(&p);
            }
            let heads: Vec<Point> = std::iter::once(self.snake.head())
                .chain(self.player2.as_ref().map(Snake::head))
                .chain(self.bots.iter().map(Snake::head))
                .collect();
            let mut placed = 0usize;
            for _ in 0..self.domino_count() * 20 {
                if placed >= self.domino_count() {
                    break;
                }
                let p = self.random_interior_point();
                let near_head = heads
                    .iter()
                    .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4);
                if !near_head
                    && !self.snake.body_map.contains_key(&p)
                    && !self.is_domino_landing_blocked(p, &next_heads)
                {
                    self.domino_tiles.insert(p);
                    self.obstacles.insert(p);
                    placed += 1;
                }
            }
            if placed > 0 {
                self.domino_reshuffles += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The dominoes stand again! ({placed})"),
                    crate::color::Color::DarkYellow,
                );
            }
            return;
        }
        if !self.tick_counter.is_multiple_of(Self::DOMINO_PERIOD) {
            return;
        }
        self.domino_waves += 1;
        // Scheduled drop: keep the field stocked while under the cap
        if self.tick_counter.is_multiple_of(Self::DOMINO_DROP_PERIOD)
            && self.domino_tiles.len() < self.domino_cap()
            && self.drop_fresh_domino(&next_heads)
        {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                "A domino drops!".to_string(),
                crate::color::Color::DarkYellow,
            );
        }
        if self.domino_tiles.is_empty() {
            // Nothing left to topple: stand one fresh domino up instead
            self.drop_fresh_domino(&next_heads);
            return;
        }
        // Topple wave: pick a random standing domino and knock it in a random
        // direction. Every domino in the chain is shoved one cell along; the
        // last domino lands on the first non-domino cell, which must be fully
        // fair, so a wave can never crush a snake.
        let dirs = [
            Direction::Up,
            Direction::Down,
            Direction::Left,
            Direction::Right,
        ];
        let frontier: Vec<Point> = self.domino_tiles.iter().copied().collect();
        let from = frontier[self.rng.gen_range(0..frontier.len())];
        let d = dirs[self.rng.gen_range(0..dirs.len())];
        let mut chain = vec![from];
        let mut landing = None;
        for _ in 0..Self::DOMINO_CHAIN_MAX {
            let cur = *chain.last().expect("chain is never empty");
            let next = Self::calculate_next_head_dir(cur, d);
            if self.domino_tiles.contains(&next) {
                chain.push(next);
                continue;
            }
            if !self.is_domino_landing_blocked(next, &next_heads) {
                landing = Some(next);
            }
            break;
        }
        let Some(landing) = landing else {
            // No fair landing: the wave fizzles and nothing moves
            return;
        };
        let fallen = chain.len();
        // The chain shoves one cell along d: the first cell is vacated and every
        // following cell (chain tail plus the landing cell) holds a domino.
        let first = chain[0];
        self.domino_tiles.remove(&first);
        self.obstacles.remove(&first);
        for &c in &chain[1..] {
            self.domino_tiles.insert(c);
            self.obstacles.insert(c);
        }
        self.domino_tiles.insert(landing);
        self.obstacles.insert(landing);
        self.domino_falls += u32::try_from(fallen).unwrap_or(u32::MAX);
        let head = self.snake.head();
        self.spawn_floating_text(
            f32::from(head.x),
            f32::from(head.y),
            format!("The dominoes topple! ({fallen})"),
            crate::color::Color::DarkYellow,
        );
    }
    fn mirage_snake_next_cells(&self) -> (Point, Option<Point>, Vec<Point>) {
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        (p1_next, p2_next, bot_next)
    }
    fn mirage_spawn_blocked(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.obstacles.contains(&p)
            || self.mirage_foods.contains_key(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.geyser_vents.contains(&p)
            || self.thorn_tiles.contains(&p)
    }
    fn spawn_mirage(&mut self) {
        let cap = (u32::from(self.width) * u32::from(self.height)) / 10;
        if u32::try_from(self.mirage_foods.len()).unwrap_or(u32::MAX) >= cap {
            return;
        }
        if self.width < 3 || self.height < 3 {
            return;
        }
        let (p1_next, p2_next, bot_next) = self.mirage_snake_next_cells();
        for _ in 0..50 {
            let x = self.rng.gen_range(1..self.width - 1);
            let y = self.rng.gen_range(1..self.height - 1);
            let pos = Point { x, y };
            if self.mirage_spawn_blocked(pos, p1_next, p2_next, &bot_next) {
                continue;
            }
            self.mirage_foods.insert(pos, Self::MIRAGE_TICKS);
            self.mirage_spawns += 1;
            self.spawn_floating_text(
                f32::from(pos.x),
                f32::from(pos.y),
                "A mirage appears!".to_string(),
                crate::color::Color::Magenta,
            );
            return;
        }
    }
    fn manage_mirage(&mut self) {
        if self.mode != GameMode::Mirage {
            return;
        }
        // A mirage shatters when any snake's head walks onto it (no food, no growth)
        let mut heads = vec![self.snake.head()];
        if let Some(p2) = &self.player2 {
            heads.push(p2.head());
        }
        for b in &self.bots {
            heads.push(b.head());
        }
        let mut shattered = 0u32;
        for h in heads {
            if self.mirage_foods.remove(&h).is_some() {
                shattered += 1;
            }
        }
        if shattered > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("Mirage shattered! (-{shattered})"),
                crate::color::Color::Magenta,
            );
        }
        // Each mirage fades one tick at a time and then vanishes
        let faded: Vec<Point> = self
            .mirage_foods
            .iter()
            .filter(|(_, ticks)| **ticks <= 1)
            .map(|(p, _)| *p)
            .collect();
        for p in faded {
            self.mirage_foods.remove(&p);
        }
        for ticks in self.mirage_foods.values_mut() {
            *ticks = ticks.saturating_sub(1);
        }
        // Periodic clear: at tick 200 of every 250-tick cycle the heat shimmers away
        if self.tick_counter == 200 {
            let n = self.mirage_foods.len();
            self.mirage_foods.clear();
            if n > 0 {
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The heat shimmers away!".to_string(),
                    crate::color::Color::Magenta,
                );
            }
            return;
        }
        // Scheduled mirage every 6th tick
        if self.tick_counter.is_multiple_of(6) {
            self.spawn_mirage();
        }
    }
    fn pinball_bumper_cap(&self) -> usize {
        (usize::from(u16::min(self.width, self.height) / 5)).clamp(4, 8)
    }
    fn pinball_next_cells(&self) -> Vec<Point> {
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let mut next = vec![Self::calculate_next_head_dir(
            self.snake.head(),
            self.snake.direction,
        )];
        if let Some(p2) = &self.player2 {
            next.push(Self::calculate_next_head_dir(p2.head(), p2.direction));
        }
        for bot in &self.bots {
            let d = bot.direction_queue.front().copied().unwrap_or(bot.direction);
            next.push(Self::calculate_next_head_dir(bot.head(), d));
        }
        next
    }
    fn pinball_avoid(&self, p: Point, next_cells: &[Point]) -> bool {
        next_cells.contains(&p)
            || self.obstacles.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| pu.location == p)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.pinball_bumpers.contains(&p)
    }
    fn pick_fair_pinball_cell(&mut self, next_cells: &[Point]) -> Option<Point> {
        let mut candidates = Vec::new();
        for x in 1..self.width.saturating_sub(1) {
            for y in 1..self.height.saturating_sub(1) {
                let p = Point { x, y };
                if !self.pinball_avoid(p, next_cells) {
                    candidates.push(p);
                }
            }
        }
        if candidates.is_empty() {
            None
        } else {
            Some(candidates[self.rng.gen_range(0..candidates.len())])
        }
    }
    fn spawn_pinball_bumpers(&mut self) {
        let next_cells = self.pinball_next_cells();
        for _ in 0..self.pinball_bumper_cap() {
            if let Some(pos) = self.pick_fair_pinball_cell(&next_cells) {
                self.pinball_bumpers.insert(pos);
                self.obstacles.insert(pos);
            }
        }
    }
    fn manage_pinball(&mut self) {
        if self.mode != GameMode::Pinball {
            return;
        }
        // The skies stay clear in Pinball mode so the bumpers are always visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale bumper records
        self.pinball_bumpers.retain(|p| self.obstacles.contains(p));
        // Periodic reset: at tick 200 of every 250-tick cycle the machine clears its bumpers
        if self.tick_counter == 200 {
            if !self.pinball_bumpers.is_empty() {
                for p in self.pinball_bumpers.drain() {
                    self.obstacles.remove(&p);
                }
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The bumpers reset!".to_string(),
                    crate::color::Color::Magenta,
                );
            }
            return;
        }
        // Every 6th tick the machine shuffles: top up towards the cap, otherwise
        // relocate one existing bumper to a fresh fair cell
        if !self.tick_counter.is_multiple_of(6) {
            return;
        }
        let cap = self.pinball_bumper_cap();
        let next_cells = self.pinball_next_cells();
        let Some(pos) = self.pick_fair_pinball_cell(&next_cells) else {
            return;
        };
        if self.pinball_bumpers.len() < cap {
            self.pinball_bumpers.insert(pos);
            self.obstacles.insert(pos);
            self.pinball_relocations += 1;
        } else {
            let existing: Vec<Point> = self.pinball_bumpers.iter().copied().collect();
            let from = existing[self.rng.gen_range(0..existing.len())];
            self.pinball_bumpers.remove(&from);
            self.obstacles.remove(&from);
            self.pinball_bumpers.insert(pos);
            self.obstacles.insert(pos);
            self.pinball_relocations += 1;
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                "Bumper moved!".to_string(),
                crate::color::Color::Magenta,
            );
        }
    }
    fn pinball_deflect(&self, head: Point) -> Option<(Point, Direction)> {
        // A bumper deflects the snake sideways like a pinball flipper: prefer a
        // perpendicular lane, fall back to a straight bounce-back, and give up
        // (lethal bumper) when every lane is blocked.
        let cur = self.snake.direction;
        let perpendiculars: [Direction; 2] = match cur {
            Direction::Left | Direction::Right => [Direction::Up, Direction::Down],
            Direction::Up | Direction::Down => [Direction::Left, Direction::Right],
        };
        let back = match cur {
            Direction::Up => Direction::Down,
            Direction::Down => Direction::Up,
            Direction::Left => Direction::Right,
            Direction::Right => Direction::Left,
        };
        let lane_free = |p: Point| {
            p.x > 0
                && p.x < self.width - 1
                && p.y > 0
                && p.y < self.height - 1
                && !self.obstacles.contains(&p)
                && !self.snake.body_map.contains_key(&p)
                && self
                    .player2
                    .as_ref()
                    .is_none_or(|p2| !p2.body_map.contains_key(&p))
                && !self.bots.iter().any(|b| b.body_map.contains_key(&p))
        };
        for d in perpendiculars {
            let p = Self::calculate_next_head_dir(head, d);
            if lane_free(p) {
                return Some((p, d));
            }
        }
        let p = Self::calculate_next_head_dir(head, back);
        if lane_free(p) {
            return Some((p, back));
        }
        None
    }
    fn manage_steamroller(&mut self) {
        if self.mode != GameMode::Steamroller {
            return;
        }
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale roller records
        self.press_cells.retain(|p| self.obstacles.contains(p));
        // Periodic reset: at tick 200 of every 250-tick cycle the roller returns home
        if self.tick_counter == 200 {
            if !self.press_cells.is_empty() || self.press_pos != 1 || self.press_dir != 1 {
                for p in self.press_cells.drain() {
                    self.obstacles.remove(&p);
                }
                self.press_pos = 1;
                self.press_dir = 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The roller resets!".to_string(),
                    crate::color::Color::DarkRed,
                );
            }
            return;
        }
        // The board's border ring is lethal already, so the roller only ever
        // sweeps the playable columns 1..=width-2.
        if self.width < 3 {
            return;
        }
        // The roller speeds up over each 250-tick cycle: one column every 4
        // ticks early on, every tick by the end of the cycle.
        let interval = if self.tick_counter < 60 {
            4_u32
        } else if self.tick_counter < 120 {
            3
        } else if self.tick_counter < 160 {
            2
        } else {
            1
        };
        if !self.tick_counter.is_multiple_of(interval) {
            return;
        }
        let max_pos = self.width - 2;
        let mut new_x = i32::from(self.press_pos) + i32::from(self.press_dir);
        if new_x < 1 || new_x > i32::from(max_pos) {
            // Ping-pong: bounce off the far edge and sweep back
            self.press_dir = -self.press_dir;
            new_x = i32::from(self.press_pos) + i32::from(self.press_dir);
        }
        if new_x < 1 || new_x > i32::from(max_pos) {
            return;
        }
        let Some(new_x) = u16::try_from(new_x).ok() else {
            return;
        };
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next =
            self.player2.as_ref().map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        let avoid = |p: &Point| {
            *p == p1_next
                || p2_next == Some(*p)
                || bot_next.contains(p)
                || self.obstacles.contains(p)
                || self.snake.body_map.contains_key(p)
                || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                || self.bots.iter().any(|b| b.body_map.contains_key(p))
                || *p == self.food
                || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                || self.mines.contains(p)
                || self.black_hole == Some(*p)
                || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                || self.bosses.iter().any(|b| b.position == *p)
                || self.companion.as_ref().is_some_and(|c| c.position == *p)
                || self.turrets.iter().any(|t| t.position == *p)
                || self.xp_gems.contains(p)
                || self.painted_tiles.contains_key(p)
                || self.equipment_boxes.contains(p)
                || self.crops.iter().any(|c| c.position == *p)
                || self.eggs_on_board.contains_key(p)
                || self.koth_zone == Some(*p)
                || self.p1_flag == Some(*p)
                || self.p2_flag == Some(*p)
                || self.resources.contains_key(p)
                || self.lasers.iter().any(|l| l.position == *p)
                || self.meteors.iter().any(|m| m.position == *p)
                || self.snow_tiles.contains(p)
                || self.sand_tiles.contains(p)
                || self.lava_tiles.contains(p)
                || self.rubble_tiles.contains(p)
                || self.seismic_rubble.contains(p)
                || self.acid_puddles.contains(p)
                || self.puddle_tiles.contains(p)
                || self.fire_tiles.contains(p)
                || self.ash_tiles.contains(p)
                || self.inferno_tiles.contains(p)
                || self.belt_tiles.contains_key(p)
                || self.ice_tiles.contains(p)
                || self.blaze_tiles.contains_key(p)
                || self.fortress_walls.contains(p)
                || self.press_cells.contains(p)
        };
        // A roller cell is never placed on a snake's body, on the cell any snake
        // is about to enter this tick, or on any entity, so the sweeping wall
        // can never crush or seal anyone; the column it just left is vacated.
        let mut line_cells = Vec::new();
        for y in 1..self.height.saturating_sub(1) {
            let p = Point {
                x: new_x,
                y,
            };
            if !avoid(&p) {
                line_cells.push(p);
            }
        }
        for p in self.press_cells.drain() {
            self.obstacles.remove(&p);
        }
        let mut erected = 0u32;
        for p in line_cells {
            self.press_cells.insert(p);
            self.obstacles.insert(p);
            erected += 1;
        }
        self.press_pos = new_x;
        self.press_moves += 1;
        if erected > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The roller advances! (+{erected})"),
                crate::color::Color::DarkRed,
            );
        }
    }

    fn manage_spike_pit(&mut self) {
        if self.mode != GameMode::SpikePit {
            return;
        }
        // The skies stay clear so the vents, cracks, and spikes are always visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale spike records
        self.spike_tiles.retain(|p, _| self.obstacles.contains(p));
        // Keep the pit armed: re-seed missing vents on fair cells
        if self.spike_vents.len() < Self::SPIKE_PIT_VENTS {
            let missing = Self::SPIKE_PIT_VENTS - self.spike_vents.len();
            let spawn_x = self.width / 2;
            let spawn_y = self.height / 2;
            for _ in 0..missing {
                let avoid_vent = |p: &Point| {
                    self.obstacles.contains(p)
                        || self.mines.contains(p)
                        || *p == self.food
                        || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                        || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                        || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                        || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                        || self.black_hole == Some(*p)
                        || self.tornado == Some(*p)
                        || self.spike_vents.contains(p)
                        || self.snake.body_map.contains_key(p)
                        || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                        || self.bots.iter().any(|b| b.body_map.contains_key(p))
                        || p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) < 5
                };
                match Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_vent,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    Some(pos) => self.spike_vents.push(pos),
                    None => break,
                }
            }
        }
        // Each spike stays up one tick less and then retracts, leaving open ground
        let retracted: Vec<Point> = self
            .spike_tiles
            .iter()
            .filter(|(_, ticks)| **ticks <= 1)
            .map(|(p, _)| *p)
            .collect();
        for p in retracted {
            self.spike_tiles.remove(&p);
            self.obstacles.remove(&p);
        }
        for ticks in self.spike_tiles.values_mut() {
            *ticks = ticks.saturating_sub(1);
        }
        // Periodic retraction: at tick 200 of every 250-tick cycle all spikes pull back
        if self.tick_counter == 200 {
            let doomed: Vec<Point> = self.spike_tiles.keys().copied().collect();
            if !doomed.is_empty() {
                for p in doomed {
                    self.spike_tiles.remove(&p);
                    self.obstacles.remove(&p);
                }
                self.spike_warnings.clear();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The spikes retract!".to_string(),
                    crate::color::Color::Red,
                );
            }
            return;
        }
        // The player's and player 2's direction queues are popped before the manage_* calls,
        // so their current direction is the one they will move in this tick; the bots are
        // popped afterwards, so for them the queued direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        // Telegraph: SPIKE_TELEGRAPH_TICKS before an eruption the threatened cells crack
        if self.tick_counter % 6 == Self::SPIKE_TELEGRAPH_TICKS % 6 {
            self.spike_warnings.clear();
            let vents = self.spike_vents.clone();
            for vent in vents {
                let mut cells = vec![vent];
                for dir in [
                    Direction::Up,
                    Direction::Down,
                    Direction::Left,
                    Direction::Right,
                ] {
                    let np = Self::calculate_next_head_dir(vent, dir);
                    if np.x < self.width && np.y < self.height {
                        cells.push(np);
                    }
                }
                for cell in cells {
                    if !self.is_spike_eruption_blocked(cell, p1_next, p2_next, &bot_next) {
                        self.spike_warnings.insert(cell);
                    }
                }
            }
            return;
        }
        // Scheduled eruption: every 6th tick each vent pops spikes on its plus-shaped area
        if !self.tick_counter.is_multiple_of(6) {
            return;
        }
        self.spike_eruptions += 1;
        self.spike_warnings.clear();
        let vents = self.spike_vents.clone();
        let mut erupted = 0u32;
        for vent in vents {
            let mut cells = vec![vent];
            for dir in [
                Direction::Up,
                Direction::Down,
                Direction::Left,
                Direction::Right,
            ] {
                let np = Self::calculate_next_head_dir(vent, dir);
                if np.x < self.width && np.y < self.height {
                    cells.push(np);
                }
            }
            for cell in cells {
                if self.is_spike_eruption_blocked(cell, p1_next, p2_next, &bot_next) {
                    continue;
                }
                // Re-erupting on an already-spiked cell just refreshes its timer
                self.spike_tiles.insert(cell, Self::SPIKE_UP_TICKS);
                self.obstacles.insert(cell);
                erupted += 1;
            }
        }
        if erupted > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("Spikes erupt! (+{erupted})"),
                crate::color::Color::Red,
            );
        }
    }
    fn is_spike_eruption_blocked(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.obstacles.contains(&p)
            || self.mines.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.thorn_tiles.contains(&p)
    }
    fn manage_tar_pit(&mut self) {
        if self.mode != GameMode::TarPit {
            return;
        }
        // The skies stay clear so the loose tar and the tar pits are always visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale tar records
        self.tar_pits.retain(|p| self.obstacles.contains(p));
        self.tar_patches
            .retain(|p| self.tar_pits.contains(p) || self.tar_warnings.contains(p));
        // Setting cycle: at TAR_DRY_TICK of every 250-tick cycle all the tar sets hard at once
        if self.tick_counter % 250 == Self::TAR_DRY_TICK {
            if !self.tar_pits.is_empty() || !self.tar_warnings.is_empty() {
                let set: Vec<Point> = self.tar_pits.iter().copied().collect();
                for p in set {
                    self.tar_pits.remove(&p);
                    self.obstacles.remove(&p);
                }
                self.tar_warnings.clear();
                self.tar_patches.clear();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The tar sets hard!".to_string(),
                    crate::color::Color::DarkYellow,
                );
            }
            return;
        }
        let (p1_next, p2_next, bot_next) = self.phase_next_cells();
        // Telegraph: TAR_TELEGRAPH_TICKS before activation the threatened cells show as loose tar
        if self.tick_counter % Self::TAR_PERIOD == Self::TAR_TELEGRAPH_TICKS % Self::TAR_PERIOD {
            self.tar_warnings.clear();
            // Seed a fresh plus-shaped pit every other cycle while under the patch cap
            if self.tick_counter % (Self::TAR_PERIOD * 2) == Self::TAR_TELEGRAPH_TICKS % Self::TAR_PERIOD
                && self.tar_patches.len() < Self::TAR_MAX_PATCHES
                && self.tar_pits.len() < Self::TAR_MAX_CELLS
            {
                let spawn_x = self.width / 2;
                let spawn_y = self.height / 2;
                let mut center = None;
                for _ in 0..64 {
                    let p = Point {
                        x: self.rng.gen_range(0..self.width),
                        y: self.rng.gen_range(0..self.height),
                    };
                    if p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) < 5 {
                        continue;
                    }
                    if !self.is_tar_cell_blocked(p, p1_next, p2_next, &bot_next) {
                        center = Some(p);
                        break;
                    }
                }
                if let Some(center) = center {
                    self.tar_patches.push(center);
                    let mut cells = vec![center];
                    for dir in [
                        Direction::Up,
                        Direction::Down,
                        Direction::Left,
                        Direction::Right,
                    ] {
                        let np = Self::calculate_next_head_dir(center, dir);
                        if np.x < self.width && np.y < self.height {
                            cells.push(np);
                        }
                    }
                    for cell in cells {
                        if !self.is_tar_cell_blocked(cell, p1_next, p2_next, &bot_next) {
                            self.tar_warnings.insert(cell);
                        }
                    }
                }
            }
            // Spreading: active pits creep into fair neighboring cells
            if !self.tar_pits.is_empty() && self.tar_pits.len() < Self::TAR_MAX_CELLS {
                let mut budget =
                    Self::TAR_SPREAD_CELLS.saturating_mul(self.tar_patches.len().max(1));
                let mut cells: Vec<Point> = self.tar_pits.iter().copied().collect();
                cells.sort_by_key(|p| (p.x, p.y));
                'spread: for cell in cells {
                    for dir in [
                        Direction::Up,
                        Direction::Down,
                        Direction::Left,
                        Direction::Right,
                    ] {
                        let np = Self::calculate_next_head_dir(cell, dir);
                        if np.x < self.width
                            && np.y < self.height
                            && !self.tar_pits.contains(&np)
                            && !self.tar_warnings.contains(&np)
                            && !self.is_tar_cell_blocked(np, p1_next, p2_next, &bot_next)
                        {
                            self.tar_warnings.insert(np);
                            budget = budget.saturating_sub(1);
                            if budget == 0 {
                                break 'spread;
                            }
                        }
                    }
                }
            }
            return;
        }
        // Activation: every TAR_PERIOD-th tick the telegraphed cells turn to tar
        if !self.tick_counter.is_multiple_of(Self::TAR_PERIOD) || self.tar_warnings.is_empty() {
            return;
        }
        self.tar_spreads += 1;
        let warned: Vec<Point> = self.tar_warnings.iter().copied().collect();
        self.tar_warnings.clear();
        let mut activated = 0u32;
        for cell in warned {
            if self.tar_pits.len() >= Self::TAR_MAX_CELLS {
                break;
            }
            if self.is_tar_cell_blocked(cell, p1_next, p2_next, &bot_next) {
                continue;
            }
            self.tar_pits.insert(cell);
            self.obstacles.insert(cell);
            activated += 1;
        }
        if activated > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("Tar spreads! (+{activated})"),
                crate::color::Color::DarkYellow,
            );
        }
    }
    // Whether a tar cell is fair to claim: never on the border ring, off-board,
    // on a snake's body, on the cell any snake is about to enter this tick, or on any entity.
    fn is_tar_cell_blocked(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        // Tar only claims interior cells (the border ring is the drawn wall)
        p.x == 0
            || p.y == 0
            || p.x >= self.width.saturating_sub(1)
            || p.y >= self.height.saturating_sub(1)
            || p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.obstacles.contains(&p)
            || self.tar_pits.contains(&p)
            || self.tar_warnings.contains(&p)
            || self.quicksand.contains(&p)
            || self.crumble_tiles.contains(&p)
            || self.domino_tiles.contains(&p)
            || self.mines.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.thorn_tiles.contains(&p)
            || self.tramp_pads.contains(&p)
            || self.blink_pads.contains(&p)
            || self.magnet_poles.keys().any(|pole| *pole == p)
            || self.polarity_poles.contains(&p)
            || self.phase_gates.contains(&p)
    }
    fn spawn_tar_patches(&mut self) {
        let spawn_x = self.width / 2;
        let spawn_y = self.height / 2;
        let (p1_next, p2_next, bot_next) = self.phase_next_cells();
        for _ in 0..Self::TAR_PATCHES {
            let mut center = None;
            for _ in 0..64 {
                let p = Point {
                    x: self.rng.gen_range(0..self.width),
                    y: self.rng.gen_range(0..self.height),
                };
                if p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) < 5 {
                    continue;
                }
                if !self.is_tar_cell_blocked(p, p1_next, p2_next, &bot_next) {
                    center = Some(p);
                    break;
                }
            }
            if let Some(center) = center {
                self.tar_patches.push(center);
                let mut cells = vec![center];
                for dir in [
                    Direction::Up,
                    Direction::Down,
                    Direction::Left,
                    Direction::Right,
                ] {
                    let np = Self::calculate_next_head_dir(center, dir);
                    if np.x < self.width && np.y < self.height {
                        cells.push(np);
                    }
                }
                for cell in cells {
                    if !self.is_tar_cell_blocked(cell, p1_next, p2_next, &bot_next) {
                        self.tar_pits.insert(cell);
                        self.obstacles.insert(cell);
                        self.spawn_particles(
                            f32::from(cell.x),
                            f32::from(cell.y),
                            6,
                            crate::color::Color::DarkYellow,
                            '~',
                        );
                    }
                }
            }
        }
    }
    fn manage_quicksand(&mut self) {
        if self.mode != GameMode::Quicksand {
            return;
        }
        // A permanent drizzle keeps the bog wet; ambient weather randomization is skipped in this mode
        self.weather = Weather::Rain;
        // Periodic drain: at tick 200 of every 250-tick cycle the whole bog dries up
        if self.tick_counter == 200 {
            if !self.quicksand.is_empty() {
                self.quicksand.clear();
                self.quicksand_sink = 0;
                self.quicksand_sink2 = 0;
                self.quicksand_bot_sinks.clear();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The bog drains!".to_string(),
                    crate::color::Color::DarkYellow,
                );
            }
            return;
        }
        // Scheduled spread: every QUICKSAND_PERIOD ticks the bog claims new cells
        if !self.tick_counter.is_multiple_of(Self::QUICKSAND_PERIOD) {
            return;
        }
        // The player's and player 2's direction queues are popped before the manage_* calls,
        // so their current direction is the one they will move in this tick; the bots are
        // popped afterwards, so for them the queued direction is the cell they are about to enter.
        let mut next_heads = vec![Self::calculate_next_head_dir(
            self.snake.head(),
            self.snake.direction,
        )];
        if let Some(p2) = &self.player2 {
            next_heads.push(Self::calculate_next_head_dir(p2.head(), p2.direction));
        }
        for b in &self.bots {
            let d = b.direction_queue.front().copied().unwrap_or(b.direction);
            next_heads.push(Self::calculate_next_head_dir(b.head(), d));
        }
        self.quicksand_spreads += 1;
        let mut claimed = 0u32;
        if self.quicksand.len() < Self::QUICKSAND_MAX_CELLS {
            if self.quicksand.is_empty() || self.rng.gen_bool(0.5) {
                // Seed a fresh patch: a fair center plus up to QUICKSAND_PATCH_CELLS
                // orthogonal cells, kept a little away from every snake head
                let heads: Vec<Point> = std::iter::once(self.snake.head())
                    .chain(self.player2.iter().map(Snake::head))
                    .chain(self.bots.iter().map(Snake::head))
                    .collect();
                let mut center = None;
                let min_x = 1 + self.safe_zone_margin;
                let max_x = (self.width - 1)
                    .saturating_sub(self.safe_zone_margin)
                    .max(min_x + 1);
                let min_y = 1 + self.safe_zone_margin;
                let max_y = (self.height - 1)
                    .saturating_sub(self.safe_zone_margin)
                    .max(min_y + 1);
                if min_x < max_x && min_y < max_y {
                    for _ in 0..100 {
                        let p = Point {
                            x: self.rng.gen_range(min_x..max_x),
                            y: self.rng.gen_range(min_y..max_y),
                        };
                        if self.snake.body_map.contains_key(&p)
                            || self.is_quicksand_cell_blocked(p, &next_heads)
                            || heads
                                .iter()
                                .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 3)
                        {
                            continue;
                        }
                        center = Some(p);
                        break;
                    }
                }
                if let Some(center) = center {
                    self.quicksand.insert(center);
                    claimed += 1;
                    let mut arms = 0;
                    for dir in [
                        Direction::Up,
                        Direction::Down,
                        Direction::Left,
                        Direction::Right,
                    ] {
                        if arms >= Self::QUICKSAND_PATCH_CELLS
                            || self.quicksand.len() >= Self::QUICKSAND_MAX_CELLS
                        {
                            break;
                        }
                        let np = Self::calculate_next_head_dir(center, dir);
                        if !self.is_quicksand_cell_blocked(np, &next_heads) {
                            self.quicksand.insert(np);
                            claimed += 1;
                            arms += 1;
                        }
                    }
                }
            } else {
                // Grow an existing patch by up to two fair neighboring cells
                let frontier: Vec<Point> = self.quicksand.iter().copied().collect();
                let from = frontier[self.rng.gen_range(0..frontier.len())];
                let mut arms = 0;
                for dir in [
                    Direction::Up,
                    Direction::Down,
                    Direction::Left,
                    Direction::Right,
                ] {
                    if arms >= 2 || self.quicksand.len() >= Self::QUICKSAND_MAX_CELLS {
                        break;
                    }
                    let np = Self::calculate_next_head_dir(from, dir);
                    if !self.is_quicksand_cell_blocked(np, &next_heads) {
                        self.quicksand.insert(np);
                        claimed += 1;
                        arms += 1;
                    }
                }
            }
        }
        if claimed > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The bog spreads! (+{claimed})"),
                crate::color::Color::DarkYellow,
            );
        }
    }
    // Whether a cell is fair for quicksand to claim: inside the playable area, never
    // on a snake's body, on the cell any snake is about to enter this tick, on any
    // entity or hazard tile, or already bog.
    fn is_quicksand_cell_blocked(&self, p: Point, next_heads: &[Point]) -> bool {
        p.x == 0
            || p.y == 0
            || p.x >= self.width.saturating_sub(1)
            || p.y >= self.height.saturating_sub(1)
            || next_heads.contains(&p)
            || self.quicksand.contains(&p)
            || self.obstacles.contains(&p)
            || self.mines.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.rocks.iter().any(|r| r.position == p)
            || self.boulders.iter().any(|b| b.position == p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.thorn_tiles.contains(&p)
            || self.spike_tiles.contains_key(&p)
            || self.press_cells.contains(&p)
            || self.pinball_bumpers.contains(&p)
            || self.tramp_pads.contains(&p)
            || (self.phase_solid && self.phase_gates.contains(&p))
    }
    // Whether a phase-gate cell is fair to solidify on: never on a snake's
    // body, on the cell any snake is about to enter this tick, or on any entity.
    fn phase_gate_clear(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        !(p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.mines.contains(&p)
            || self.black_hole == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.tornado.is_some_and(|t| t == p)
            || self.geyser_jets.contains_key(&p)
            || self.geyser_vents.contains(&p)
            || self.pinball_bumpers.contains(&p)
            || self.mirage_foods.contains_key(&p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p))
    }
    fn phase_next_cells(&self) -> (Point, Option<Point>, Vec<Point>) {
        // The player's and player 2's direction queues are popped before the
        // manage_* calls, so their current direction is the one they will move
        // in this tick; the bots are popped afterwards, so for them the queued
        // direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        (p1_next, p2_next, bot_next)
    }
    fn manage_phase_shift(&mut self) {
        if self.mode != GameMode::PhaseShift {
            return;
        }
        // Scheduled phase flip: every PHASE_PERIOD-th tick the gates toggle
        // between solid (lethal) and ghost (passable).
        if self.tick_counter.is_multiple_of(Self::PHASE_PERIOD) {
            self.phase_solid = !self.phase_solid;
            self.phase_shifts += 1;
            let head = self.snake.head();
            if self.phase_solid {
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The gates solidify!".to_string(),
                    crate::color::Color::Magenta,
                );
            } else {
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The gates phase out!".to_string(),
                    crate::color::Color::DarkMagenta,
                );
            }
        }
        // Keep the obstacle mirror in sync every tick (this also self-heals if
        // something else cleared obstacles mid-tick, e.g. a Bomb). A gate only
        // becomes solid on a fair cell, so the phase can never crush a snake.
        let (p1_next, p2_next, bot_next) = self.phase_next_cells();
        if self.phase_solid {
            let fair: Vec<Point> = self
                .phase_gates
                .iter()
                .copied()
                .filter(|p| self.phase_gate_clear(*p, p1_next, p2_next, &bot_next))
                .collect();
            for p in fair {
                self.obstacles.insert(p);
            }
        } else {
            for p in &self.phase_gates {
                self.obstacles.remove(p);
            }
        }
    }
    fn tramp_pad_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 60).clamp(3, 8)
    }
    // A cell a launch path may pass through or land on must be fair right now:
    // in bounds, free of snakes (bodies and the cells they are about to enter)
    // and of every entity or lethal tile, so a fling can never directly kill.
    fn tramp_cell_free(&self, p: Point) -> bool {
        if !self.singularity_cell_free(p) {
            return false;
        }
        if self.lightning_column.is_some_and(|col| p.x == col)
            || self.crossfire_beam_cell(p)
            || self.fire_tiles.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.seismic_rubble.contains(&p)
        {
            return false;
        }
        if self.mode == GameMode::BattleRoyale && !self.within_safe_zone(p, 0) {
            return false;
        }
        true
    }
    // When a snake's next cell is a launch pad, fling its head up to
    // TRAMP_LAUNCH cells (TRAMP_LAUNCH_CHARGED while overcharged) along its
    // current direction. Only whole fair paths are accepted, longest first;
    // the pad cell itself stays walkable, so if no launch is fair the snake
    // simply rests on the pad and can never be flung into a kill.
    fn tramp_launch(&self, pad: Point, dir: Direction) -> Option<Point> {
        if self.mode != GameMode::Trampoline {
            return None;
        }
        if !self.tramp_pads.contains(&pad) {
            return None;
        }
        let dists: &[u16] = if self.tramp_overcharge > 0 {
            &[Self::TRAMP_LAUNCH_CHARGED, 4, Self::TRAMP_LAUNCH, 2, 1]
        } else {
            &[Self::TRAMP_LAUNCH, 2, 1]
        };
        for &k in dists {
            let mut dest = pad;
            let mut ok = true;
            for _ in 0..k {
                dest = Self::calculate_next_head_dir(dest, dir);
                if !self.tramp_cell_free(dest) {
                    ok = false;
                    break;
                }
            }
            if ok {
                return Some(dest);
            }
        }
        None
    }
    fn manage_trampoline(&mut self) {
        if self.mode != GameMode::Trampoline {
            return;
        }
        // Pads under fresh obstacles are scrapped
        self.tramp_pads.retain(|p| !self.obstacles.contains(p));
        // Overcharge counts down once per tick
        if self.tramp_overcharge > 0 {
            self.tramp_overcharge = self.tramp_overcharge.saturating_sub(1);
        }
        // Scheduled shuffle: every 24th tick the whole layout rearranges and
        // every pad relocates to a fresh fair cell. Fairness: a new pad never
        // lands on a snake, on the cell any snake is about to enter, on any
        // entity or hazard, or within 4 cells of any snake head.
        if self.tick_counter.is_multiple_of(24) {
            let count = self.tramp_pad_count();
            let next_heads = self.singularity_next_heads();
            let heads: Vec<Point> = std::iter::once(self.snake.head())
                .chain(self.player2.as_ref().map(Snake::head))
                .chain(self.bots.iter().map(Snake::head))
                .collect();
            let old_pads = std::mem::take(&mut self.tramp_pads);
            let avoid_pad = |p: &Point| {
                self.obstacles.contains(p)
                    || self.mines.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                    || self.bosses.iter().any(|b| b.position == *p)
                    || self.companion.as_ref().is_some_and(|c| c.position == *p)
                    || self.turrets.iter().any(|t| t.position == *p)
                    || self.lasers.iter().any(|l| l.position == *p)
                    || self.meteors.iter().any(|m| m.position == *p)
                    || self.xp_gems.contains(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || next_heads.contains(p)
                    || old_pads.contains(p)
                    || self.fire_tiles.contains(p)
                    || self.acid_puddles.contains(p)
                    || self.puddle_tiles.contains(p)
                    || self.lava_tiles.contains(p)
                    || self.inferno_tiles.contains(p)
                    || self.blaze_tiles.contains_key(p)
                    || self.seismic_rubble.contains(p)
                    || self.ice_tiles.contains(p)
                    || self.belt_tiles.contains_key(p)
                    || self.pinball_bumpers.contains(p)
                    || heads
                        .iter()
                        .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4)
            };
            let mut placed = 0usize;
            for _ in 0..count {
                if let Some(p) = Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_pad,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    self.tramp_pads.insert(p);
                    placed += 1;
                }
            }
            if placed > 0 {
                self.tramp_shuffles += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The pads rearrange! ({placed})"),
                    crate::color::Color::Yellow,
                );
            }
        }
    }
    fn blink_pad_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 60).clamp(3, 8)
    }
    // A cell a blink may land on must be fair right now: in bounds within the
    // safe-zone margin, free of snakes (bodies and the cells they are about to
    // enter) and of every entity or lethal tile, and not another pad, so a
    // blink can never directly kill or chain into a second pad.
    fn blink_cell_free(&self, p: Point) -> bool {
        self.tramp_cell_free(p) && !self.blink_pads.contains(&p)
    }
    // When a snake's next cell is a blink pad, teleport its head to a random
    // fair cell ("Blink!"). While overcharged the destination is biased to a
    // fair cell adjacent to the food. The pad cell itself stays walkable, so
    // if no destination is fair the snake simply rests on the pad and can
    // never be blinked into a kill.
    fn blink_teleport(&mut self, pad: Point) -> Option<Point> {
        if self.mode != GameMode::Blink || !self.blink_pads.contains(&pad) {
            return None;
        }
        if self.blink_overcharge > 0 {
            let mut targets = vec![self.food];
            if let Some((bp, _)) = self.bonus_food {
                targets.push(bp);
            }
            let mut near_food: Vec<Point> = Vec::new();
            for target in targets {
                for dir in [
                    Direction::Up,
                    Direction::Down,
                    Direction::Left,
                    Direction::Right,
                ] {
                    let cell = Self::calculate_next_head_dir(target, dir);
                    if self.blink_cell_free(cell) {
                        near_food.push(cell);
                    }
                }
            }
            if !near_food.is_empty() {
                let idx = self.rng.gen_range(0..near_food.len());
                return Some(near_food[idx]);
            }
        }
        // Fall back to any fair cell: collect the fair cells first so the rng
        // is not borrowed while self is read
        let mut fair: Vec<Point> = Vec::new();
        for y in 0..self.height {
            for x in 0..self.width {
                let p = Point { x, y };
                if self.blink_cell_free(p) {
                    fair.push(p);
                }
            }
        }
        if fair.is_empty() {
            return None;
        }
        let idx = self.rng.gen_range(0..fair.len());
        Some(fair[idx])
    }
    fn manage_blink(&mut self) {
        if self.mode != GameMode::Blink {
            return;
        }
        // Pads under fresh obstacles are scrapped
        self.blink_pads.retain(|p| !self.obstacles.contains(p));
        // Overcharge counts down once per tick
        if self.blink_overcharge > 0 {
            self.blink_overcharge = self.blink_overcharge.saturating_sub(1);
        }
        // Scheduled scatter: every BLINK_PERIOD-th tick the whole layout
        // rearranges and every pad relocates to a fresh fair cell. Fairness: a
        // new pad never lands on a snake, on the cell any snake is about to
        // enter, on any entity or hazard, or within 4 cells of any snake head.
        if self.tick_counter.is_multiple_of(Self::BLINK_PERIOD) {
            let count = self.blink_pad_count();
            let next_heads = self.singularity_next_heads();
            let heads: Vec<Point> = std::iter::once(self.snake.head())
                .chain(self.player2.as_ref().map(Snake::head))
                .chain(self.bots.iter().map(Snake::head))
                .collect();
            let old_pads = std::mem::take(&mut self.blink_pads);
            let avoid_pad = |p: &Point| {
                self.obstacles.contains(p)
                    || self.mines.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                    || self.bosses.iter().any(|b| b.position == *p)
                    || self.companion.as_ref().is_some_and(|c| c.position == *p)
                    || self.turrets.iter().any(|t| t.position == *p)
                    || self.lasers.iter().any(|l| l.position == *p)
                    || self.meteors.iter().any(|m| m.position == *p)
                    || self.xp_gems.contains(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || next_heads.contains(p)
                    || old_pads.contains(p)
                    || self.fire_tiles.contains(p)
                    || self.acid_puddles.contains(p)
                    || self.puddle_tiles.contains(p)
                    || self.lava_tiles.contains(p)
                    || self.inferno_tiles.contains(p)
                    || self.blaze_tiles.contains_key(p)
                    || self.seismic_rubble.contains(p)
                    || self.ice_tiles.contains(p)
                    || self.belt_tiles.contains_key(p)
                    || self.pinball_bumpers.contains(p)
                    || self.tramp_pads.contains(p)
                    || self.polarity_poles.contains(p)
                    || heads
                        .iter()
                        .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4)
            };
            let mut placed = 0usize;
            for _ in 0..count {
                if let Some(p) = Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_pad,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    self.blink_pads.insert(p);
                    placed += 1;
                }
            }
            if placed > 0 {
                self.blink_shuffles += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The pads scatter! ({placed})"),
                    crate::color::Color::Cyan,
                );
            }
        }
    }
    fn polarity_pole_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 80).clamp(2, 6)
    }
    // A cell a magnetic shove may move a head onto must be fair right now:
    // in bounds, free of snakes (bodies and the cells they are about to enter)
    // and of every entity or lethal tile, so a shove can never directly kill.
    fn polarity_cell_free(&self, p: Point) -> bool {
        if !self.singularity_cell_free(p) {
            return false;
        }
        if self.lightning_column.is_some_and(|col| p.x == col)
            || self.fire_tiles.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.seismic_rubble.contains(&p)
        {
            return false;
        }
        if self.mode == GameMode::BattleRoyale && !self.within_safe_zone(p, 0) {
            return false;
        }
        true
    }
    // On a polarity-flip tick, shove the head one cell toward the nearest pole
    // while attracting, or away from it while repelling. Only fair destination
    // cells are accepted (dominant axis first, then the other axis); if none is
    // fair the snake is not shoved at all, so a pole can never shove a kill.
    fn polarity_shove(&self, head: Point, is_player: bool) -> Option<Point> {
        if self.mode != GameMode::Polarity {
            return None;
        }
        if !self.tick_counter.is_multiple_of(Self::POLARITY_FLIP_PERIOD) {
            return None;
        }
        if is_player && self.polarity_shield > 0 {
            return None;
        }
        let (pole, _) = self
            .polarity_poles
            .iter()
            .map(|p| {
                (
                    *p,
                    p.x.abs_diff(head.x).saturating_add(p.y.abs_diff(head.y)),
                )
            })
            .min_by_key(|(_, d)| *d)?;
        let dx = pole.x.abs_diff(head.x);
        let dy = pole.y.abs_diff(head.y);
        if dx == 0 && dy == 0 {
            return None;
        }
        let toward = |step_x: i32, step_y: i32| {
            let dest = Point {
                x: (i32::from(head.x) + step_x).clamp(0, i32::from(self.width) - 1) as u16,
                y: (i32::from(head.y) + step_y).clamp(0, i32::from(self.height) - 1) as u16,
            };
            if self.polarity_cell_free(dest) {
                Some(dest)
            } else {
                None
            }
        };
        let sx = if pole.x > head.x { 1 } else { -1 };
        let sy = if pole.y > head.y { 1 } else { -1 };
        let (ax, ay) = if self.polarity_attract { (sx, sy) } else { (-sx, -sy) };
        if dx >= dy {
            toward(ax, 0).or_else(|| toward(0, ay))
        } else {
            toward(0, ay).or_else(|| toward(ax, 0))
        }
    }
    fn manage_polarity(&mut self) {
        if self.mode != GameMode::Polarity {
            return;
        }
        // Poles under fresh obstacles are scrapped
        self.polarity_poles.retain(|p| !self.obstacles.contains(p));
        // The player's shield counts down once per tick
        if self.polarity_shield > 0 {
            self.polarity_shield = self.polarity_shield.saturating_sub(1);
        }
        // Scheduled flip: every POLARITY_FLIP_PERIOD-th tick the field flips
        // between attracting and repelling; the shove itself is applied where
        // belt_shove/tramp_launch are applied, on this same tick.
        if self.tick_counter.is_multiple_of(Self::POLARITY_FLIP_PERIOD) {
            self.polarity_attract = !self.polarity_attract;
            self.polarity_flips += 1;
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                if self.polarity_attract {
                    "Polarity flipped: Attract!".to_string()
                } else {
                    "Polarity flipped: Repel!".to_string()
                },
                if self.polarity_attract {
                    crate::color::Color::Red
                } else {
                    crate::color::Color::Blue
                },
            );
        }
        // Scheduled shuffle: every POLARITY_SHUFFLE_PERIOD-th tick every pole
        // relocates to a fresh fair cell. Fairness: a new pole never lands on a
        // snake, on the cell any snake is about to enter, on any entity or
        // hazard, or within 4 cells of any snake head.
        if self.tick_counter.is_multiple_of(Self::POLARITY_SHUFFLE_PERIOD) {
            let count = self.polarity_pole_count();
            let next_heads = self.singularity_next_heads();
            let heads: Vec<Point> = std::iter::once(self.snake.head())
                .chain(self.player2.as_ref().map(Snake::head))
                .chain(self.bots.iter().map(Snake::head))
                .collect();
            let old_poles = std::mem::take(&mut self.polarity_poles);
            let avoid_pole = |p: &Point| {
                self.obstacles.contains(p)
                    || self.mines.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                    || self.bosses.iter().any(|b| b.position == *p)
                    || self.companion.as_ref().is_some_and(|c| c.position == *p)
                    || self.turrets.iter().any(|t| t.position == *p)
                    || self.lasers.iter().any(|l| l.position == *p)
                    || self.meteors.iter().any(|m| m.position == *p)
                    || self.xp_gems.contains(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || next_heads.contains(p)
                    || old_poles.contains(p)
                    || self.fire_tiles.contains(p)
                    || self.acid_puddles.contains(p)
                    || self.puddle_tiles.contains(p)
                    || self.lava_tiles.contains(p)
                    || self.inferno_tiles.contains(p)
                    || self.blaze_tiles.contains_key(p)
                    || self.seismic_rubble.contains(p)
                    || self.ice_tiles.contains(p)
                    || self.belt_tiles.contains_key(p)
                    || self.pinball_bumpers.contains(p)
                    || self.tramp_pads.contains(p)
                    || heads
                        .iter()
                        .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4)
            };
            let mut placed = 0usize;
            for _ in 0..count {
                if let Some(p) = Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_pole,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    self.polarity_poles.insert(p);
                    placed += 1;
                }
            }
            if placed > 0 {
                self.polarity_shuffles += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The poles rearrange! ({placed})"),
                    crate::color::Color::Magenta,
                );
            }
        }
    }
    // A cell on the active crossfire beam (lethal right now)
    #[must_use]
    pub fn crossfire_beam_cell(&self, p: Point) -> bool {
        self.crossfire_beam_ticks > 0
            && self
                .crossfire_target
                .is_some_and(|(col, row)| p.x == col || p.y == row)
    }
    // A cell on the crossfire cross that is lethal now or telegraphed to fire soon
    #[must_use]
    pub fn crossfire_danger_cell(&self, p: Point) -> bool {
        (self.crossfire_beam_ticks > 0 || self.crossfire_warn_ticks > 0)
            && self
                .crossfire_target
                .is_some_and(|(col, row)| p.x == col || p.y == row)
    }
    // Fairness: never schedule a cross whose column or row any snake currently
    // occupies (a beam sweeps the whole line, so body segments count too) or is
    // about to enter this tick. The player's and player 2's direction queues are
    // popped before the manage_* calls, so their current direction is the one they
    // will move in this tick; the bots are popped afterwards, so for them the queued
    // direction is the cell they are about to enter.
    fn pick_safe_cross(&mut self) -> Option<(u16, u16)> {
        let mut forbidden_cols: Vec<u16> = Vec::new();
        let mut forbidden_rows: Vec<u16> = Vec::new();
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        forbidden_cols.push(self.snake.head().x);
        forbidden_rows.push(self.snake.head().y);
        forbidden_cols.push(p1_next.x);
        forbidden_rows.push(p1_next.y);
        for p in self.snake.body_map.keys() {
            forbidden_cols.push(p.x);
            forbidden_rows.push(p.y);
        }
        if let Some(p2) = &self.player2 {
            let p2_next = Self::calculate_next_head_dir(p2.head(), p2.direction);
            forbidden_cols.push(p2.head().x);
            forbidden_rows.push(p2.head().y);
            forbidden_cols.push(p2_next.x);
            forbidden_rows.push(p2_next.y);
            for p in p2.body_map.keys() {
                forbidden_cols.push(p.x);
                forbidden_rows.push(p.y);
            }
        }
        for b in &self.bots {
            let d = b.direction_queue.front().copied().unwrap_or(b.direction);
            let next = Self::calculate_next_head_dir(b.head(), d);
            forbidden_cols.push(b.head().x);
            forbidden_rows.push(b.head().y);
            forbidden_cols.push(next.x);
            forbidden_rows.push(next.y);
            for p in b.body_map.keys() {
                forbidden_cols.push(p.x);
                forbidden_rows.push(p.y);
            }
        }
        let margin = if self.mode == GameMode::BattleRoyale {
            self.safe_zone_margin
        } else {
            0
        };
        let min_x = margin + 1;
        let max_x = (self.width - 1).saturating_sub(margin).max(min_x);
        let min_y = margin + 1;
        let max_y = (self.height - 1).saturating_sub(margin).max(min_y);
        let cols: Vec<u16> = (min_x..max_x)
            .filter(|x| !forbidden_cols.contains(x))
            .collect();
        let rows: Vec<u16> = (min_y..max_y)
            .filter(|y| !forbidden_rows.contains(y))
            .collect();
        if cols.is_empty() || rows.is_empty() {
            return None;
        }
        let col = cols[self.rng.gen_range(0..cols.len())];
        let row = rows[self.rng.gen_range(0..rows.len())];
        Some((col, row))
    }
    fn manage_crossfire(&mut self) {
        if self.mode != GameMode::Crossfire {
            return;
        }
        // The skies stay clear so the telegraph and the beam are always visible
        self.weather = Weather::Clear;
        // Periodic reset: at tick 200 of every 250-tick cycle the crossfire dies down
        if self.tick_counter == 200 {
            if self.crossfire_target.is_some() || self.crossfire_beam_ticks > 0 {
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The crossfire dies down!".to_string(),
                    crate::color::Color::Yellow,
                );
            }
            self.crossfire_target = None;
            self.crossfire_warn_ticks = 0;
            self.crossfire_beam_ticks = 0;
            return;
        }
        // An active beam counts down; when it expires the cross is over
        if self.crossfire_beam_ticks > 0 {
            self.crossfire_beam_ticks -= 1;
            if self.crossfire_beam_ticks == 0 {
                self.crossfire_target = None;
            }
            return;
        }
        // The telegraph counts down; at zero the beam fires
        if self.crossfire_warn_ticks > 0 {
            self.crossfire_warn_ticks -= 1;
            if self.crossfire_warn_ticks == 0 {
                self.crossfire_beam_ticks = Self::CROSSFIRE_BEAM_TICKS;
                self.crossfire_strikes += 1;
                crate::game::beep();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "Crossfire!".to_string(),
                    crate::color::Color::Red,
                );
            }
            return;
        }
        // Schedule a new cross on every CROSSFIRE_PERIOD-th tick, on fair lines only
        if self.tick_counter.is_multiple_of(Self::CROSSFIRE_PERIOD)
            && let Some((col, row)) = self.pick_safe_cross()
        {
            self.crossfire_target = Some((col, row));
            self.crossfire_warn_ticks = Self::CROSSFIRE_TELEGRAPH_TICKS;
        }
    }
    fn magnet_pole_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 150).clamp(2, 6)
    }
    fn spawn_magnet_poles(&mut self) {
        self.magnet_poles.clear();
        let spawn_x = self.width / 2;
        let spawn_y = self.height / 2;
        let heads: Vec<Point> = std::iter::once(self.snake.head())
            .chain(self.player2.as_ref().map(Snake::head))
            .chain(self.bots.iter().map(Snake::head))
            .collect();
        let next_heads = self.singularity_next_heads();
        for _ in 0..self.magnet_pole_count() {
            // Fairness: a pole never spawns on a snake, on the cell any snake is
            // about to enter, on any entity or hazard, on another pole, or within
            // 5 cells of the spawn point.
            let avoid_pole = |p: &Point| {
                self.obstacles.contains(p)
                    || self.mines.contains(p)
                    || *p == self.food
                    || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                    || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                    || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                    || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                    || self.black_hole == Some(*p)
                    || self.tornado == Some(*p)
                    || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                    || self.bosses.iter().any(|b| b.position == *p)
                    || self.companion.as_ref().is_some_and(|c| c.position == *p)
                    || self.turrets.iter().any(|t| t.position == *p)
                    || self.lasers.iter().any(|l| l.position == *p)
                    || self.meteors.iter().any(|m| m.position == *p)
                    || self.rocks.iter().any(|r| r.position == *p)
                    || self.xp_gems.contains(p)
                    || self.tramp_pads.contains(p)
                    || self.pinball_bumpers.contains(p)
                    || self.magnet_poles.contains_key(p)
                    || self.snake.body_map.contains_key(p)
                    || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                    || self.bots.iter().any(|b| b.body_map.contains_key(p))
                    || next_heads.contains(p)
                    || self.fire_tiles.contains(p)
                    || self.acid_puddles.contains(p)
                    || self.puddle_tiles.contains(p)
                    || self.lava_tiles.contains(p)
                    || self.inferno_tiles.contains(p)
                    || self.blaze_tiles.contains_key(p)
                    || self.seismic_rubble.contains(p)
                    || heads
                        .iter()
                        .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4)
                    || p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) < 5
            };
            if let Some(p) = Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid_pole,
                &mut self.rng,
                self.safe_zone_margin,
            ) {
                let attract = self.rng.gen_bool(0.5);
                self.magnet_poles.insert(p, attract);
            }
        }
    }
    fn manage_magnet(&mut self) {
        if self.mode != GameMode::Magnet {
            return;
        }
        // Poles under fresh obstacles are demagnetized
        self.magnet_poles.retain(|p, _| !self.obstacles.contains(p));
        // Scheduled relocation: every MAGNET_RELOCATE_PERIOD-th tick the whole
        // field rearranges and every pole moves to a fresh fair cell with a
        // re-rolled polarity. Fairness: a relocated pole never lands on a snake,
        // on the cell any snake is about to enter, on any entity or hazard, or
        // within 4 cells of any snake head.
        if self.tick_counter.is_multiple_of(Self::MAGNET_RELOCATE_PERIOD) {
            let count = self.magnet_pole_count();
            let next_heads = self.singularity_next_heads();
            let heads: Vec<Point> = std::iter::once(self.snake.head())
                .chain(self.player2.as_ref().map(Snake::head))
                .chain(self.bots.iter().map(Snake::head))
                .collect();
            self.magnet_poles.clear();
            let mut placed = 0usize;
            for _ in 0..count {
                let avoid_pole = |p: &Point| {
                    self.obstacles.contains(p)
                        || self.mines.contains(p)
                        || *p == self.food
                        || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                        || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                        || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                        || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                        || self.black_hole == Some(*p)
                        || self.tornado == Some(*p)
                        || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                        || self.bosses.iter().any(|b| b.position == *p)
                        || self.companion.as_ref().is_some_and(|c| c.position == *p)
                        || self.turrets.iter().any(|t| t.position == *p)
                        || self.lasers.iter().any(|l| l.position == *p)
                        || self.meteors.iter().any(|m| m.position == *p)
                        || self.rocks.iter().any(|r| r.position == *p)
                        || self.xp_gems.contains(p)
                        || self.tramp_pads.contains(p)
                        || self.pinball_bumpers.contains(p)
                        || self.snake.body_map.contains_key(p)
                        || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                        || self.bots.iter().any(|b| b.body_map.contains_key(p))
                        || next_heads.contains(p)
                        || self.fire_tiles.contains(p)
                        || self.acid_puddles.contains(p)
                        || self.puddle_tiles.contains(p)
                        || self.lava_tiles.contains(p)
                        || self.inferno_tiles.contains(p)
                        || self.blaze_tiles.contains_key(p)
                        || self.seismic_rubble.contains(p)
                        || heads
                            .iter()
                            .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < 4)
                };
                if let Some(p) = Self::get_random_empty_point(
                    self.width,
                    self.height,
                    &self.snake,
                    avoid_pole,
                    &mut self.rng,
                    self.safe_zone_margin,
                ) {
                    let attract = self.rng.gen_bool(0.5);
                    self.magnet_poles.insert(p, attract);
                    placed += 1;
                }
            }
            if placed > 0 {
                self.magnet_relocations += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The poles shift! ({placed})"),
                    crate::color::Color::Cyan,
                );
            }
        }
    }
    // The pulse destination for a head shoved one cell in `dir`. Fairness: a
    // pulse never shoves a snake out of bounds (unless the board wraps), into
    // an obstacle, or into anything lethal or occupied, so a pulse can never
    // directly kill.
    fn magnet_destination(&self, head: Point, dir: Direction) -> Option<Point> {
        let dest = self.gust_destination(head, dir)?;
        // The cells the *other* snakes are about to enter are off limits (the
        // pulsed snake's own next cell is fine - it is simply where it goes next)
        let mut snakes: Vec<&Snake> = vec![&self.snake];
        if let Some(p2) = &self.player2 {
            snakes.push(p2);
        }
        snakes.extend(self.bots.iter());
        let other_next_head_blocked = snakes
            .iter()
            .filter(|s| s.head() != head)
            .map(|s| Self::calculate_next_head_dir(s.head(), s.direction))
            .any(|next_head| next_head == dest);
        if self.fire_tiles.contains(&dest)
            || self.acid_puddles.contains(&dest)
            || self.puddle_tiles.contains(&dest)
            || self.inferno_tiles.contains(&dest)
            || self.blaze_tiles.contains_key(&dest)
            || self.seismic_rubble.contains(&dest)
            || self.portals.is_some_and(|(p1, p2)| dest == p1 || dest == p2)
            || other_next_head_blocked
            || self.meteors.iter().any(|m| self.meteor_would_hit(*m, dest, 1))
        {
            return None;
        }
        Some(dest)
    }
    // The pulse step for a head: one cell toward (attract pole) or away from
    // (repel pole) the nearest pole along the dominant axis. Returns None when
    // the head sits on a pole or no fair destination exists.
    fn magnet_pulse_step(&self, head: Point) -> Option<(Point, bool)> {
        let (pole, attract) = self
            .magnet_poles
            .iter()
            .min_by_key(|(p, _)| p.x.abs_diff(head.x).saturating_add(p.y.abs_diff(head.y)))?;
        let dx = i32::from(pole.x) - i32::from(head.x);
        let dy = i32::from(pole.y) - i32::from(head.y);
        if dx == 0 && dy == 0 {
            return None;
        }
        let toward = if dx.abs() >= dy.abs() {
            if dx > 0 {
                Direction::Right
            } else {
                Direction::Left
            }
        } else if dy > 0 {
            Direction::Down
        } else {
            Direction::Up
        };
        let dir = if *attract {
            toward
        } else {
            match toward {
                Direction::Up => Direction::Down,
                Direction::Down => Direction::Up,
                Direction::Left => Direction::Right,
                Direction::Right => Direction::Left,
            }
        };
        self.magnet_destination(head, dir).map(|dest| (dest, *attract))
    }
    fn manage_magnet_pulse(&mut self) {
        if self.mode != GameMode::Magnet {
            return;
        }
        // A magnetic pulse sweeps the whole board on every MAGNET_PULSE_PERIOD-th tick
        if !self.tick_counter.is_multiple_of(Self::MAGNET_PULSE_PERIOD)
            || self.state != GameState::Playing
            || self.magnet_poles.is_empty()
        {
            return;
        }
        self.magnet_pulses += 1;
        // One shared pulse shoves every snake one cell toward or away from its
        // nearest pole. Snakes are pulsed sequentially so earlier pulses are
        // respected by later checks.
        if let Some((dest, attract)) = self.magnet_pulse_step(self.snake.head()) {
            self.snake.move_to(dest, false);
            self.spawn_floating_text(
                f32::from(dest.x),
                f32::from(dest.y),
                if attract { "Pulled!" } else { "Pushed!" }.to_string(),
                if attract {
                    crate::color::Color::Cyan
                } else {
                    crate::color::Color::Red
                },
            );
        }
        let p2_step = self
            .player2
            .as_ref()
            .and_then(|p2| self.magnet_pulse_step(p2.head()));
        if let Some((dest, attract)) = p2_step {
            if let Some(p2) = &mut self.player2 {
                p2.move_to(dest, false);
            }
            self.spawn_floating_text(
                f32::from(dest.x),
                f32::from(dest.y),
                if attract { "Pulled!" } else { "Pushed!" }.to_string(),
                if attract {
                    crate::color::Color::Cyan
                } else {
                    crate::color::Color::Red
                },
            );
        }
        for i in 0..self.bots.len() {
            if let Some((dest, attract)) = self.magnet_pulse_step(self.bots[i].head()) {
                self.bots[i].move_to(dest, false);
                self.spawn_floating_text(
                    f32::from(dest.x),
                    f32::from(dest.y),
                    if attract { "Pulled!" } else { "Pushed!" }.to_string(),
                    if attract {
                        crate::color::Color::Cyan
                    } else {
                        crate::color::Color::Red
                    },
                );
            }
        }
    }
    const fn gale_dir_name(dir: Direction) -> &'static str {
        match dir {
            Direction::Up => "Up",
            Direction::Down => "Down",
            Direction::Left => "Left",
            Direction::Right => "Right",
        }
    }
    // A cell is in a falling meteor's lane when it sits at or below the meteor
    // in its column (or the drifted column for sweeping meteors); a gust must
    // never drop a snake into a lane a meteor is about to sweep through.
    fn gale_meteor_lane(&self, p: Point) -> bool {
        self.meteors.iter().any(|m| {
            p.y >= m.position.y
                && (p.x == m.position.x
                    || (m.vx != 0 && (p.x == m.position.x + 1 || p.x == m.position.x - 1)))
        })
    }
    // The wind shoves a snake whose head just moved one extra cell along the
    // gale direction — but only onto a cell that is fair right now, outside
    // every meteor lane, and not already claimed by another snake's head this
    // tick, so a gust can never push anyone into a kill or into another head.
    fn gale_shove(&self, head: Point, braced: bool, claimed: &HashSet<Point>) -> Option<Point> {
        if self.mode != GameMode::Gale || braced {
            return None;
        }
        let dest = Self::calculate_next_head_dir(head, self.gale_dir);
        if dest.x == 0 || dest.x >= self.width - 1 || dest.y == 0 || dest.y >= self.height - 1 {
            return None;
        }
        if claimed.contains(&dest) || !self.tramp_cell_free(dest) || self.gale_meteor_lane(dest) {
            return None;
        }
        Some(dest)
    }
    fn manage_gale(&mut self) {
        if self.mode != GameMode::Gale {
            return;
        }
        // A brace counts down once per tick
        if self.gale_braces > 0 {
            self.gale_braces = self.gale_braces.saturating_sub(1);
        }
        // Scheduled shift: every GALE_PERIOD-th tick the wind turns to a new
        // direction different from the current one
        if self.tick_counter.is_multiple_of(Self::GALE_PERIOD) {
            let dirs = [Direction::Up, Direction::Down, Direction::Left, Direction::Right];
            let mut new_dir = self.gale_dir;
            while new_dir == self.gale_dir {
                new_dir = dirs[self.rng.gen_range(0..dirs.len())];
            }
            self.gale_dir = new_dir;
            self.gale_shifts += 1;
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The wind shifts {}!", Self::gale_dir_name(new_dir)),
                crate::color::Color::Cyan,
            );
        }
    }
    fn crumble_tile_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 50).clamp(4, 10)
    }
    fn crumble_cap(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 40).clamp(6, 16)
    }
    // A cell a new crack may appear on must be fair right now: in bounds within
    // the safe-zone margin, free of snakes (bodies and the cells they are about
    // to enter) and every entity, and clear of every hazard tile, so cracking
    // the floor can never seal or kill anyone.
    fn crumble_cell_free(&self, p: Point) -> bool {
        if !self.singularity_cell_free(p) {
            return false;
        }
        if self.lightning_column.is_some_and(|col| p.x == col)
            || self.fire_tiles.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.seismic_rubble.contains(&p)
            || self.ice_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.pinball_bumpers.contains(&p)
            || self.tramp_pads.contains(&p)
            || self.polarity_poles.contains(&p)
            || self.quicksand.contains(&p)
            || self.blink_pads.contains(&p)
            || self.phase_gates.contains(&p)
            || self.thorn_tiles.contains(&p)
            || self.spike_tiles.contains_key(&p)
            || self.spike_warnings.contains(&p)
            || self.mirage_foods.contains_key(&p)
            || self.crumble_tiles.contains(&p)
        {
            return false;
        }
        if self.mode == GameMode::BattleRoyale && !self.within_safe_zone(p, 0) {
            return false;
        }
        true
    }
    // Fair crack candidates: every free cell at least min_head_dist (Manhattan)
    // away from the given snake heads.
    fn crumble_candidates(&self, heads: &[Point], min_head_dist: u16) -> Vec<Point> {
        let margin = self.safe_zone_margin;
        let min_x = 1 + margin;
        let max_x = (self.width - 1).saturating_sub(margin).max(min_x + 1);
        let min_y = 1 + margin;
        let max_y = (self.height - 1).saturating_sub(margin).max(min_y + 1);
        let mut out = Vec::new();
        for y in min_y..max_y {
            for x in min_x..max_x {
                let p = Point { x, y };
                if self.crumble_cell_free(p)
                    && heads.iter().all(|h| {
                        p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) >= min_head_dist
                    })
                {
                    out.push(p);
                }
            }
        }
        out
    }
    // A crack cell is claimed while any snake is about to enter it or an entity
    // sits on it; such a crack must not collapse this tick.
    fn crumble_cell_claimed(&self, p: Point, next_heads: &[Point]) -> bool {
        next_heads.contains(&p)
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| pu.location == p)
            || self.mines.contains(&p)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
    }
    fn spawn_crumble_cracks(&mut self) {
        self.crumble_tiles.clear();
        self.crumble_collapses = 0;
        self.crumble_cracks = 0;
        let spawn = Point {
            x: self.width / 2,
            y: self.height / 2,
        };
        let mut candidates = self.crumble_candidates(&[spawn], 5);
        for _ in 0..self.crumble_tile_count() {
            if candidates.is_empty() {
                break;
            }
            let idx = self.rng.gen_range(0..candidates.len());
            let p = candidates.swap_remove(idx);
            self.crumble_tiles.insert(p);
        }
    }
    fn manage_crumble(&mut self) {
        if self.mode != GameMode::Crumble {
            return;
        }
        // The skies stay clear so the cracks are always visible
        self.weather = Weather::Clear;
        // Collapse: a crack under a snake head turns into a permanent pit as
        // that head leaves, i.e. at the start of the tick before the snake
        // moves. Obstacle death is only ever checked on the new head, so the
        // mover can never be crushed by its own trail, and a crack never
        // collapses while another snake is about to enter its cell or an
        // entity sits on it, so a collapse can never kill anyone cheaply.
        let next_heads = self.singularity_next_heads();
        let mut heads: Vec<Point> = vec![self.snake.head()];
        if let Some(p2) = &self.player2 {
            heads.push(p2.head());
        }
        heads.extend(self.bots.iter().map(Snake::head));
        let mut collapsed: Vec<Point> = Vec::new();
        for h in &heads {
            if self.crumble_tiles.contains(h) && !self.crumble_cell_claimed(*h, &next_heads) {
                collapsed.push(*h);
            }
        }
        for p in collapsed {
            self.crumble_tiles.remove(&p);
            self.obstacles.insert(p);
            self.crumble_collapses += 1;
            self.spawn_floating_text(
                f32::from(p.x),
                f32::from(p.y),
                "Crumble!".to_string(),
                crate::color::Color::DarkYellow,
            );
        }
        // Scheduled cracking: every CRUMBLE_PERIOD ticks fresh cracks appear on
        // fair cells (up to the cap), never on a snake, on the cell any snake is
        // about to enter, on any entity or hazard tile, or close to a snake head
        if self.tick_counter.is_multiple_of(Self::CRUMBLE_PERIOD) {
            let cap = self.crumble_cap();
            let need =
                Self::CRUMBLE_NEW_PER_PERIOD.min(cap.saturating_sub(self.crumble_tiles.len()));
            if need > 0 {
                let mut candidates = self.crumble_candidates(&heads, 3);
                let mut spawned = 0usize;
                while spawned < need && !candidates.is_empty() {
                    let idx = self.rng.gen_range(0..candidates.len());
                    let p = candidates.swap_remove(idx);
                    self.crumble_tiles.insert(p);
                    spawned += 1;
                }
                if spawned > 0 {
                    self.crumble_cracks += u32::try_from(spawned).unwrap_or(u32::MAX);
                    let head = self.snake.head();
                    self.spawn_floating_text(
                        f32::from(head.x),
                        f32::from(head.y),
                        format!("The floor cracks! ({spawned})"),
                        crate::color::Color::DarkYellow,
                    );
                }
            }
        }
        // Periodic fill: at tick 200 of every 250-tick cycle the remaining
        // cracks fill back in without ever becoming pits
        if self.tick_counter == 200 && !self.crumble_tiles.is_empty() {
            self.crumble_tiles.clear();
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                "The cracks fill in!".to_string(),
                crate::color::Color::DarkYellow,
            );
        }
    }    fn elev_shaft_count(&self) -> usize {
        (usize::from(self.width) * usize::from(self.height) / 160).clamp(2, 5)
    }
    // A cell a lift may deposit a snake on must be fair right now: in bounds,
    // free of snakes (bodies and the cells they are about to enter) and of
    // every entity or lethal tile, so a ride can never directly kill.
    fn elev_cell_free(&self, p: Point) -> bool {
        if !self.singularity_cell_free(p) {
            return false;
        }
        if self.lightning_column.is_some_and(|col| p.x == col)
            || self.fire_tiles.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.seismic_rubble.contains(&p)
        {
            return false;
        }
        if self.mode == GameMode::BattleRoyale && !self.within_safe_zone(p, 0) {
            return false;
        }
        true
    }
    // A shaft end must never be placed on a snake, on the cell any snake is
    // about to enter, on any entity or hazard tile, on another shaft, or too
    // close to a spawn point or snake head.
    fn elev_cell_blocked(
        &self,
        p: Point,
        spawn: Point,
        min_spawn_dist: u16,
        heads: &[Point],
        min_head_dist: u16,
        old_shafts: &[(Point, Point)],
    ) -> bool {
        self.obstacles.contains(&p)
            || self.mines.contains(&p)
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| p == pu.location)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.rocks.iter().any(|r| r.position == p)
            || self.xp_gems.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || old_shafts.iter().any(|(s1, s2)| p == *s1 || p == *s2)
            || self.fire_tiles.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.seismic_rubble.contains(&p)
            || self.ice_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.pinball_bumpers.contains(&p)
            || self.tramp_pads.contains(&p)
            || p.x.abs_diff(spawn.x).saturating_add(p.y.abs_diff(spawn.y)) < min_spawn_dist
            || heads
                .iter()
                .any(|h| p.x.abs_diff(h.x).saturating_add(p.y.abs_diff(h.y)) < min_head_dist)
    }
    // One fair candidate cell for a shaft end, sampled like
    // get_random_empty_point but with the elevator-specific fairness rules.
    fn random_elev_end(
        &mut self,
        spawn: Point,
        min_spawn_dist: u16,
        heads: &[Point],
        min_head_dist: u16,
        old_shafts: &[(Point, Point)],
    ) -> Option<Point> {
        let next_heads = self.singularity_next_heads();
        let mut all_heads = heads.to_vec();
        all_heads.extend_from_slice(&next_heads);
        let min_x = 1 + self.safe_zone_margin;
        let max_x = (self.width - 1).saturating_sub(self.safe_zone_margin).max(min_x + 1);
        let min_y = 1 + self.safe_zone_margin;
        let max_y = (self.height - 1).saturating_sub(self.safe_zone_margin).max(min_y + 1);
        if min_x >= max_x || min_y >= max_y {
            return None;
        }
        for i in 0..100 {
            let x = self.rng.gen_range(min_x..max_x);
            let y = self.rng.gen_range(min_y..max_y);
            let p = Point { x, y };
            if !self.snake.body_map.contains_key(&p)
                && !next_heads.contains(&p)
                && !self.elev_cell_blocked(p, spawn, min_spawn_dist, &all_heads, min_head_dist, old_shafts)
            {
                return Some(p);
            }
            if i == 99 {
                let mut empty = Vec::new();
                for y_ in min_y..max_y {
                    for x_ in min_x..max_x {
                        let p_ = Point { x: x_, y: y_ };
                        if !self.snake.body_map.contains_key(&p_)
                            && !next_heads.contains(&p_)
                            && !self.elev_cell_blocked(p_, spawn, min_spawn_dist, &all_heads, min_head_dist, old_shafts)
                        {
                            empty.push(p_);
                        }
                    }
                }
                if !empty.is_empty() {
                    let idx = self.rng.gen_range(0..empty.len());
                    return Some(empty[idx]);
                }
                return None;
            }
        }
        None
    }
    // (Re)build the lift layout: `count` shafts, each a pair of cells in the
    // same column at least ELEV_MIN_GAP rows apart, on fair cells only.
    fn place_elev_shafts(&mut self, count: usize, spawn: Point, min_spawn_dist: u16, min_head_dist: u16) {
        let heads: Vec<Point> = std::iter::once(self.snake.head())
            .chain(self.player2.as_ref().map(Snake::head))
            .chain(self.bots.iter().map(Snake::head))
            .collect();
        let old_shafts = std::mem::take(&mut self.elev_shafts);
        let next_heads = self.singularity_next_heads();
        let mut all_heads = heads;
        all_heads.extend_from_slice(&next_heads);
        let mut placed: Vec<(Point, Point)> = Vec::new();
        let min_y = 1 + self.safe_zone_margin;
        let max_y = (self.height - 1).saturating_sub(self.safe_zone_margin);
        for _ in 0..count {
            let mut done = false;
            for _ in 0..25 {
                if done {
                    break;
                }
                let Some(a) = self.random_elev_end(spawn, min_spawn_dist, &all_heads, min_head_dist, &old_shafts)
                else {
                    break;
                };
                let up = self.rng.gen_bool(0.5);
                for _ in 0..8 {
                    let gap = self.rng.gen_range(Self::ELEV_MIN_GAP..=Self::ELEV_MAX_GAP);
                    let b = if up {
                        Point { x: a.x, y: a.y.saturating_sub(gap) }
                    } else {
                        Point { x: a.x, y: a.y.saturating_add(gap) }
                    };
                    if b.y < min_y || b.y >= max_y {
                        continue;
                    }
                    if next_heads.contains(&b)
                        || self.elev_cell_blocked(b, spawn, min_spawn_dist, &all_heads, min_head_dist, &old_shafts)
                    {
                        continue;
                    }
                    if placed.iter().any(|(s1, s2)| a == *s1 || a == *s2 || b == *s1 || b == *s2) {
                        continue;
                    }
                    placed.push((a, b));
                    done = true;
                    break;
                }
            }
        }
        self.elev_shafts = placed;
        self.elev_cooldowns = vec![0; self.elev_shafts.len()];
    }
    fn spawn_elevators(&mut self) {
        self.elev_shafts.clear();
        self.elev_cooldowns.clear();
        let spawn = Point { x: self.width / 2, y: self.height / 2 };
        self.place_elev_shafts(self.elev_shaft_count(), spawn, 5, 3);
    }
    // A shaft end is walkable; when a snake's next head cell is one end of a
    // shaft that is not recharging, the head is lifted to the other end.
    // Only a fair destination is accepted; otherwise the snake simply rests
    // on the walkable cell, so a lift can never directly kill.
    fn elev_ride(&self, cell: Point) -> Option<(usize, Point)> {
        if self.mode != GameMode::Elevator {
            return None;
        }
        let idx = self
            .elev_shafts
            .iter()
            .position(|(a, b)| *a == cell || *b == cell)?;
        if self.elev_overcharge == 0 && self.elev_cooldowns.get(idx).copied().unwrap_or(0) > 0 {
            return None;
        }
        let (a, b) = self.elev_shafts[idx];
        let dest = if a == cell { b } else { a };
        if !self.elev_cell_free(dest) {
            return None;
        }
        Some((idx, dest))
    }
    fn manage_elevator(&mut self) {
        if self.mode != GameMode::Elevator {
            return;
        }
        // Shafts with an end under a fresh obstacle or lethal tile are scrapped
        let shafts = std::mem::take(&mut self.elev_shafts);
        let cooldowns = std::mem::take(&mut self.elev_cooldowns);
        let mut kept_shafts = Vec::with_capacity(shafts.len());
        let mut kept_cooldowns = Vec::with_capacity(cooldowns.len());
        for (i, (a, b)) in shafts.into_iter().enumerate() {
            let clear = |p: Point| {
                !self.obstacles.contains(&p)
                    && !self.fire_tiles.contains(&p)
                    && !self.acid_puddles.contains(&p)
                    && !self.puddle_tiles.contains(&p)
                    && !self.lava_tiles.contains(&p)
                    && !self.inferno_tiles.contains(&p)
                    && !self.blaze_tiles.contains_key(&p)
                    && !self.seismic_rubble.contains(&p)
            };
            if clear(a) && clear(b) {
                kept_shafts.push((a, b));
                kept_cooldowns.push(cooldowns.get(i).copied().unwrap_or(0));
            }
        }
        self.elev_shafts = kept_shafts;
        self.elev_cooldowns = kept_cooldowns;
        // Cooldowns and the overcharge timer count down once per tick
        for cd in &mut self.elev_cooldowns {
            *cd = cd.saturating_sub(1);
        }
        if self.elev_overcharge > 0 {
            self.elev_overcharge = self.elev_overcharge.saturating_sub(1);
        }
        // Scheduled relocation: every ELEV_SHUFFLE_PERIOD-th tick the whole
        // lift layout shifts to fresh fair cells. Fairness: a new end never
        // lands on a snake, on the cell any snake is about to enter, on any
        // entity or hazard, on another shaft, or within min_head_dist of any
        // snake head.
        if self.tick_counter.is_multiple_of(Self::ELEV_SHUFFLE_PERIOD) {
            let spawn = Point { x: self.width / 2, y: self.height / 2 };
            self.place_elev_shafts(self.elev_shaft_count(), spawn, 0, 3);
            if !self.elev_shafts.is_empty() {
                self.elev_shuffles += 1;
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    format!("The elevators shift! ({})", self.elev_shafts.len()),
                    crate::color::Color::Cyan,
                );
            }
        }
    }
    fn manage_mire(&mut self) {
        if self.mode != GameMode::Mire {
            return;
        }
        // The skies stay clear so the cracks and pools are always visible
        self.weather = Weather::Clear;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale mire records
        self.mire_cells.retain(|p, _| self.obstacles.contains(p));
        // Each pool dries up one tick earlier and then disappears, leaving open ground
        let dried: Vec<Point> = self
            .mire_cells
            .iter()
            .filter(|(_, ticks)| **ticks <= 1)
            .map(|(p, _)| *p)
            .collect();
        for p in dried {
            self.mire_cells.remove(&p);
            self.obstacles.remove(&p);
        }
        for ticks in self.mire_cells.values_mut() {
            *ticks = ticks.saturating_sub(1);
        }
        // Periodic settling: at tick 200 of every 250-tick cycle all mire dries up
        if self.tick_counter == 200 {
            let doomed: Vec<Point> = self.mire_cells.keys().copied().collect();
            if !doomed.is_empty() {
                for p in doomed {
                    self.mire_cells.remove(&p);
                    self.obstacles.remove(&p);
                }
                self.mire_warnings.clear();
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The mire settles!".to_string(),
                    crate::color::Color::DarkYellow,
                );
            }
            return;
        }
        // The player's and player 2's direction queues are popped before the manage_* calls,
        // so their current direction is the one they will move in this tick; the bots are
        // popped afterwards, so for them the queued direction is the cell they are about to enter.
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next = self
            .player2
            .as_ref()
            .map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        // Telegraph: MIRE_TELEGRAPH_TICKS before a wave the threatened cells crack
        if self.tick_counter % Self::MIRE_PERIOD == Self::MIRE_TELEGRAPH_TICKS % Self::MIRE_PERIOD {
            self.mire_warnings.clear();
            let spawn_x = self.width / 2;
            let spawn_y = self.height / 2;
            let margin = self.safe_zone_margin;
            let min_x = 1 + margin;
            let max_x = (self.width - 1).saturating_sub(margin).max(min_x + 1);
            let min_y = 1 + margin;
            let max_y = (self.height - 1).saturating_sub(margin).max(min_y + 1);
            let mut candidates: Vec<Point> = Vec::new();
            for x in min_x..max_x {
                for y in min_y..max_y {
                    let p = Point { x, y };
                    if !self.mire_cell_blocked(p, p1_next, p2_next, &bot_next)
                        && !self.mire_warnings.contains(&p)
                        && p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) >= 5
                    {
                        candidates.push(p);
                    }
                }
            }
            for _ in 0..Self::MIRE_PER_WAVE {
                if candidates.is_empty() {
                    break;
                }
                let idx = self.rng.gen_range(0..candidates.len());
                let p = candidates.swap_remove(idx);
                self.mire_warnings.insert(p);
            }
            return;
        }
        // Scheduled wave: every MIRE_PERIOD-th tick the warned cells sink into pools
        if !self.tick_counter.is_multiple_of(Self::MIRE_PERIOD) {
            return;
        }
        self.mire_waves += 1;
        let warned: Vec<Point> = self.mire_warnings.drain().collect();
        let mut sunk = 0u32;
        for cell in warned {
            if self.mire_cell_blocked(cell, p1_next, p2_next, &bot_next) {
                continue;
            }
            // Re-sinking an already-pooled cell just refreshes its timer
            self.mire_cells.insert(cell, Self::MIRE_POOL_TICKS);
            self.obstacles.insert(cell);
            sunk += 1;
        }
        if sunk > 0 {
            let head = self.snake.head();
            self.spawn_floating_text(
                f32::from(head.x),
                f32::from(head.y),
                format!("The mire claims {sunk} cell(s)!"),
                crate::color::Color::DarkYellow,
            );
        }
    }
    // Whether a mire cell is unfair to sink on: never on a snake's body, on the
    // cell any snake is about to enter this tick, or on any entity.
    fn mire_cell_blocked(
        &self,
        p: Point,
        p1_next: Point,
        p2_next: Option<Point>,
        bot_next: &[Point],
    ) -> bool {
        p == p1_next
            || p2_next == Some(p)
            || bot_next.contains(&p)
            || self.obstacles.contains(&p)
            || self.mines.contains(&p)
            || self.snake.body_map.contains_key(&p)
            || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(&p))
            || self.bots.iter().any(|b| b.body_map.contains_key(&p))
            || p == self.food
            || self.bonus_food.is_some_and(|(bp, _)| p == bp)
            || self.poison_food.is_some_and(|(pp, _)| p == pp)
            || self.power_up.as_ref().is_some_and(|pu| pu.location == p)
            || self.portals.is_some_and(|(p1, p2)| p == p1 || p == p2)
            || self.black_hole == Some(p)
            || self.tornado == Some(p)
            || self.goblin.as_ref().is_some_and(|g| g.position == p)
            || self.bosses.iter().any(|b| b.position == p)
            || self.companion.as_ref().is_some_and(|c| c.position == p)
            || self.turrets.iter().any(|t| t.position == p)
            || self.xp_gems.contains(&p)
            || self.painted_tiles.contains_key(&p)
            || self.equipment_boxes.contains(&p)
            || self.crops.iter().any(|c| c.position == p)
            || self.eggs_on_board.contains_key(&p)
            || self.koth_zone == Some(p)
            || self.p1_flag == Some(p)
            || self.p2_flag == Some(p)
            || self.resources.contains_key(&p)
            || self.lasers.iter().any(|l| l.position == p)
            || self.meteors.iter().any(|m| m.position == p)
            || self.snow_tiles.contains(&p)
            || self.sand_tiles.contains(&p)
            || self.lava_tiles.contains(&p)
            || self.rubble_tiles.contains(&p)
            || self.seismic_rubble.contains(&p)
            || self.acid_puddles.contains(&p)
            || self.puddle_tiles.contains(&p)
            || self.fire_tiles.contains(&p)
            || self.ash_tiles.contains(&p)
            || self.inferno_tiles.contains(&p)
            || self.belt_tiles.contains_key(&p)
            || self.ice_tiles.contains(&p)
            || self.blaze_tiles.contains_key(&p)
            || self.fortress_walls.contains(&p)
            || self.geyser_vents.contains(&p)
            || self.geyser_jets.contains_key(&p)
            || self.thorn_tiles.contains(&p)
            || self.pinball_bumpers.contains(&p)
            || self.mirage_foods.contains_key(&p)
            || self.tramp_pads.contains(&p)
            || self.quicksand.contains(&p)
            || self.crumble_tiles.contains(&p)
    }
    fn spawn_mire_warnings(&mut self) {
        self.mire_cells.clear();
        self.mire_warnings.clear();
        self.mire_waves = 0;
        let spawn_x = self.width / 2;
        let spawn_y = self.height / 2;
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| {
                let d = b.direction_queue.front().copied().unwrap_or(b.direction);
                Self::calculate_next_head_dir(b.head(), d)
            })
            .collect();
        let margin = self.safe_zone_margin;
        let min_x = 1 + margin;
        let max_x = (self.width - 1).saturating_sub(margin).max(min_x + 1);
        let min_y = 1 + margin;
        let max_y = (self.height - 1).saturating_sub(margin).max(min_y + 1);
        let mut candidates: Vec<Point> = Vec::new();
        for x in min_x..max_x {
            for y in min_y..max_y {
                let p = Point { x, y };
                if !self.mire_cell_blocked(p, p1_next, None, &bot_next)
                    && !self.mire_warnings.contains(&p)
                    && p.x.abs_diff(spawn_x).saturating_add(p.y.abs_diff(spawn_y)) >= 5
                {
                    candidates.push(p);
                }
            }
        }
        for _ in 0..Self::MIRE_INITIAL_WARNINGS {
            if candidates.is_empty() {
                break;
            }
            let idx = self.rng.gen_range(0..candidates.len());
            let p = candidates.swap_remove(idx);
            self.mire_warnings.insert(p);
        }
    }
    fn spawn_phase_gates(&mut self) {
        self.phase_gates.clear();
        self.phase_solid = true;
        self.phase_shifts = 0;
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        // Two vertical gate walls at the one-third and two-thirds columns,
        // each with one gap of two consecutive rows so the board stays crossable.
        let gap_len = 2u16;
        for col in [self.width / 3, self.width * 2 / 3] {
            if col == 0 || col >= self.width.saturating_sub(1) || self.height <= gap_len + 1 {
                continue;
            }
            let gap_start = self.rng.gen_range(1..self.height - gap_len);
            for y in 1..self.height.saturating_sub(1) {
                if y >= gap_start && y < gap_start + gap_len {
                    continue;
                }
                let p = Point { x: col, y };
                if self.phase_gate_clear(p, p1_next, None, &[]) {
                    self.phase_gates.insert(p);
                }
            }
        }
        // The phase starts solid: mirror the fair gates into obstacles.
        let fair: Vec<Point> = self
            .phase_gates
            .iter()
            .copied()
            .filter(|p| self.phase_gate_clear(*p, p1_next, None, &[]))
            .collect();
        for p in fair {
            self.obstacles.insert(p);
        }
    }
    fn manage_monsoon(&mut self) {
        if self.mode != GameMode::Monsoon {
            return;
        }
        // The monsoon never breaks in Monsoon mode
        self.weather = Weather::Rain;
        // Self-heal: if something else cleared obstacles (e.g. a Bomb), drop stale puddle records
        self.puddle_tiles.retain(|p| self.obstacles.contains(p));
        // Periodic drain: the rain pauses and all accumulated puddles dry up
        if self.tick_counter == 200 {
            if !self.puddle_tiles.is_empty() {
                for p in self.puddle_tiles.drain() {
                    self.obstacles.remove(&p);
                }
                let head = self.snake.head();
                self.spawn_floating_text(
                    f32::from(head.x),
                    f32::from(head.y),
                    "The rain drains away!".to_string(),
                    crate::color::Color::Blue,
                );
            }
            return;
        }
        // Scheduled downpour: every 6th tick the rain is guaranteed to fall hard
        if !self.tick_counter.is_multiple_of(6) {
            return;
        }
        self.monsoon_downpours += 1;
        let cap = (u32::from(self.width) * u32::from(self.height)) / 10;
        let puddle_count = u32::try_from(self.puddle_tiles.len()).unwrap_or(u32::MAX);
        let p1_next = Self::calculate_next_head_dir(self.snake.head(), self.snake.direction);
        let p2_next =
            self.player2.as_ref().map(|p2| Self::calculate_next_head_dir(p2.head(), p2.direction));
        let bot_next: Vec<Point> = self
            .bots
            .iter()
            .map(|b| Self::calculate_next_head_dir(b.head(), b.direction))
            .collect();
        let avoid = |p: &Point| {
            *p == p1_next
                || p2_next == Some(*p)
                || bot_next.contains(p)
                || self.obstacles.contains(p)
                || self.snake.body_map.contains_key(p)
                || self.player2.as_ref().is_some_and(|p2| p2.body_map.contains_key(p))
                || self.bots.iter().any(|b| b.body_map.contains_key(p))
                || *p == self.food
                || self.bonus_food.is_some_and(|(bp, _)| *p == bp)
                || self.poison_food.is_some_and(|(pp, _)| *p == pp)
                || self.power_up.as_ref().is_some_and(|pu| *p == pu.location)
                || self.portals.is_some_and(|(p1, p2)| *p == p1 || *p == p2)
                || self.mines.contains(p)
                || self.black_hole == Some(*p)
                || self.goblin.as_ref().is_some_and(|g| g.position == *p)
                || self.bosses.iter().any(|b| b.position == *p)
                || self.companion.as_ref().is_some_and(|c| c.position == *p)
                || self.turrets.iter().any(|t| t.position == *p)
                || self.xp_gems.contains(p)
                || self.painted_tiles.contains_key(p)
                || self.equipment_boxes.contains(p)
                || self.crops.iter().any(|c| c.position == *p)
                || self.eggs_on_board.contains_key(p)
                || self.koth_zone == Some(*p)
                || self.p1_flag == Some(*p)
                || self.p2_flag == Some(*p)
                || self.resources.contains_key(p)
                || self.lasers.iter().any(|l| l.position == *p)
                || self.meteors.iter().any(|m| m.position == *p)
                || self.rocks.iter().any(|b| b.position == *p)
        };
        // A fresh puddle splashes down on a random fair empty cell
        let drop_pos = if puddle_count < cap {
            Self::get_random_empty_point(
                self.width,
                self.height,
                &self.snake,
                avoid,
                &mut self.rng,
                self.safe_zone_margin,
            )
        } else {
            None
        };
        // The downpour also swells one existing puddle onto an adjacent fair cell
        let puddles: Vec<Point> = self.puddle_tiles.iter().copied().collect();
        let swell_pos = if !puddles.is_empty() && puddle_count + u32::from(drop_pos.is_some()) < cap
        {
            let base = puddles[self.rng.gen_range(0..puddles.len())];
            let options: Vec<Point> =
                [Direction::Up, Direction::Down, Direction::Left, Direction::Right]
                    .iter()
                    .map(|dir| Self::calculate_next_head_dir(base, *dir))
                    .filter(|np| np.x < self.width && np.y < self.height && !avoid(np))
                    .collect();
            if options.is_empty() {
                None
            } else {
                Some(options[self.rng.gen_range(0..options.len())])
            }
        } else {
            None
        };
        if let Some(pos) = drop_pos {
            self.puddle_tiles.insert(pos);
            self.obstacles.insert(pos);
        }
        if let Some(np) = swell_pos {
            self.puddle_tiles.insert(np);
            self.obstacles.insert(np);
        }
    }
